  Lesson(id:"trois_hg_l2",chapterId:"trois_hg_c",title:"Lire une carte",content:"Une carte représente un espace à l’aide de signes conventionnels. Le titre indique le sujet, la légende explique les symboles et l’échelle permet de comparer la distance sur la carte à la distance réelle. Le nord est généralement placé en haut.",summary:"Lire le titre, la légende et l’échelle avant d’interpréter une carte.",keyPoints:["Lire le titre, la légende et l’échelle avant d’interpréter une carte."]),
  Lesson(id:"trois_ecm_l1",chapterId:"trois_ecm_c",title:"Droits et devoirs de l’élève",content:"À l’école, chaque élève a droit à la sécurité, au respect et à l’apprentissage. Il doit aussi respecter les personnes, le règlement intérieur, le matériel et les horaires. Les droits et les devoirs permettent une vie collective juste.",summary:"Les droits protègent chacun ; les devoirs organisent la vie commune.",keyPoints:["Les droits protègent chacun ; les devoirs organisent la vie commune."]),
  Lesson(id:"trois_ecm_l2",chapterId:"trois_ecm_c",title:"Protéger le bien commun",content:"Le bien commun comprend les biens et les espaces utilisés par tous : école, route, eau, équipements publics. Chacun doit les préserver, éviter le gaspillage et signaler les dégradations. La solidarité consiste aussi à aider les autres sans discrimination.",summary:"Protéger les biens publics et agir avec respect et solidarité.",keyPoints:["Protéger les biens publics et agir avec respect et solidarité."]),
  Lesson(id:"trois_eps_l1",chapterId:"trois_eps_c",title:"S’échauffer avant l’effort",content:"L’échauffement prépare progressivement le corps à l’activité physique. Il commence par des mouvements doux, puis mobilise les articulations et augmente progressivement l’intensité. Il réduit le risque de blessure et doit être adapté à l’âge et à l’activité.",summary:"Commencer doucement, mobiliser les articulations et augmenter progressivement l’effort.",keyPoints:["Commencer doucement, mobiliser les articulations et augmenter progressivement l’effort."]),
  Lesson(id:"trois_eps_l2",chapterId:"trois_eps_c",title:"Respecter les règles et les partenaires",content:"Dans un jeu collectif, les règles garantissent l’équité et la sécurité. Le fair-play consiste à respecter les adversaires, les partenaires, l’arbitre et les décisions. On gagne ou on perd sans violence ni humiliation.",summary:"Respecter les règles, l’arbitre et les autres ; refuser la violence.",keyPoints:["Respecter les règles, l’arbitre et les autres ; refuser la violence."]),
  Lesson(id:"cp1_eps_l1",chapterId:"cp1_eps_c",title:"Les règles des jeux collectifs",content:"Dans un jeu collectif, les règles organisent les équipes, les déplacements et les points. Il faut respecter les consignes, les partenaires et les adversaires. On joue sans violence et on accepte les décisions de l’arbitre.",summary:"Respecter les règles, les partenaires et les adversaires.",keyPoints:["Respecter les règles, les partenaires et les adversaires."]),
  Lesson(id:"cp1_eps_l2",chapterId:"cp1_eps_c",title:"L’échauffement et l’hygiène",content:"Avant une activité physique, on commence par des mouvements doux et progressifs. Après l’effort, on récupère, on boit de l’eau et on se lave. Des vêtements adaptés et des chaussures convenables contribuent à la sécurité.",summary:"S’échauffer, boire de l’eau, récupérer et garder une bonne hygiène.",keyPoints:["S’échauffer, boire de l’eau, récupérer et garder une bonne hygiène."]),
  Lesson(id:"cp1_art_l1",chapterId:"cp1_art_c",title:"Les couleurs et les formes",content:"Les couleurs peuvent être primaires ou obtenues par mélange. Les formes géométriques et les lignes permettent de composer un dessin. On peut observer son environnement puis représenter les objets avec différentes techniques.",summary:"Observer, choisir les couleurs et organiser les formes dans une composition.",keyPoints:["Observer, choisir les couleurs et organiser les formes dans une composition."]),
  Lesson(id:"cp1_art_l2",chapterId:"cp1_art_c",title:"Chant, rythme et expression",content:"Le rythme organise les sons dans le temps. Pour chanter ensemble, on écoute le groupe, on respecte le départ et on garde une cadence régulière. Le dessin, le chant, la danse et le théâtre sont des moyens d’expression.",summary:"Écouter, suivre le rythme et respecter les autres dans une création.",keyPoints:["Écouter, suivre le rythme et respecter les autres dans une création."]),
  Lesson(id:"cp1_civ_l1",chapterId:"cp1_civ_c",title:"Le respect et la solidarité",content:"Chaque personne mérite le respect. À l’école et dans la famille, on écoute les autres, on refuse les insultes et on aide ceux qui en ont besoin. La solidarité consiste à agir ensemble pour le bien de tous.",summary:"Respecter les personnes, écouter et aider sans exclure.",keyPoints:["Respecter les personnes, écouter et aider sans exclure."]),
  Lesson(id:"cp1_civ_l2",chapterId:"cp1_civ_c",title:"Les biens communs et l’environnement",content:"L’eau, les arbres, les salles de classe et le matériel collectif doivent être protégés. Chacun peut éviter le gaspillage, garder les lieux propres et jeter les déchets dans les poubelles.",summary:"Protéger les biens communs et garder son environnement propre.",keyPoints:["Protéger les biens communs et garder son environnement propre."]),
  Lesson(id:"cp2_eps_l1",chapterId:"cp2_eps_c",title:"Les règles des jeux collectifs",content:"Dans un jeu collectif, les règles organisent les équipes, les déplacements et les points. Il faut respecter les consignes, les partenaires et les adversaires. On joue sans violence et on accepte les décisions de l’arbitre.",summary:"Respecter les règles, les partenaires et les adversaires.",keyPoints:["Respecter les règles, les partenaires et les adversaires."]),
