  Lesson(id:"cm2_civ_l2",chapterId:"cm2_civ_c",title:"Les biens communs et l’environnement",content:"L’eau, les arbres, les salles de classe et le matériel collectif doivent être protégés. Chacun peut éviter le gaspillage, garder les lieux propres et jeter les déchets dans les poubelles.",summary:"Protéger les biens communs et garder son environnement propre.",keyPoints:["Protéger les biens communs et garder son environnement propre."]),
  Lesson(id:"special_seconde_a4_l1",chapterId:"special_seconde_a4_c",title:"Notions fondamentales – A4",content:"L’analyse littéraire étudie un texte en tenant compte de son genre, de son thème, de son organisation et des procédés d’écriture. Une interprétation s’appuie sur des indices précis du texte.",summary:"Maîtriser les notions essentielles de culture littéraire et analyse de textes.",keyPoints:["Maîtriser les notions essentielles de culture littéraire et analyse de textes."]),
  Lesson(id:"special_seconde_a4_l2",chapterId:"special_seconde_a4_c",title:"Méthode et application",content:"L’argumentation défend une idée avec une thèse, des arguments et des exemples. Un paragraphe cohérent relie les idées avec des connecteurs logiques.",summary:"Appliquer les connaissances de culture littéraire et analyse de textes dans une situation concrète.",keyPoints:["Appliquer les connaissances de culture littéraire et analyse de textes dans une situation concrète."]),
  Lesson(id:"special_seconde_c_l1",chapterId:"special_seconde_c_c",title:"Notions fondamentales – C",content:"Une démarche expérimentale consiste à formuler une hypothèse, définir un protocole, mesurer, traiter les résultats et conclure en tenant compte des incertitudes.",summary:"Maîtriser les notions essentielles de grandeurs physiques et lois.",keyPoints:["Maîtriser les notions essentielles de grandeurs physiques et lois."]),
  Lesson(id:"special_seconde_c_l2",chapterId:"special_seconde_c_c",title:"Méthode et application",content:"Une mesure scientifique doit toujours comporter…",summary:"Appliquer les connaissances de grandeurs physiques et lois dans une situation concrète.",keyPoints:["Appliquer les connaissances de grandeurs physiques et lois dans une situation concrète."]),
  Lesson(id:"special_seconde_d_l1",chapterId:"special_seconde_d_c",title:"Notions fondamentales – D",content:"La nutrition et la reproduction sont des fonctions essentielles du vivant. Les organes coopèrent dans des appareils pour assurer le fonctionnement de l’organisme.",summary:"Maîtriser les notions essentielles de cellule et organisation du vivant.",keyPoints:["Maîtriser les notions essentielles de cellule et organisation du vivant."]),
  Lesson(id:"special_seconde_d_l2",chapterId:"special_seconde_d_c",title:"Méthode et application",content:"L’unité de base du vivant est…",summary:"Appliquer les connaissances de cellule et organisation du vivant dans une situation concrète.",keyPoints:["Appliquer les connaissances de cellule et organisation du vivant dans une situation concrète."]),
  Lesson(id:"special_seconde_g1_l1",chapterId:"special_seconde_g1_c",title:"Notions fondamentales – G1",content:"Le classement permet de retrouver les documents. Un dossier est organisé selon un plan cohérent, avec des dates, des références et des règles de confidentialité.",summary:"Maîtriser les notions essentielles de documents et communication en entreprise.",keyPoints:["Maîtriser les notions essentielles de documents et communication en entreprise."]),
