  Exercise(id:'cp2_ae3_polite',lessonId:'cp2_al3_classroom_actions',question:'Which word makes a request polite?',options:['Please','Run','Bag'],correctIndex:0,explanation:'“Please” signifie « s’il te plaît » ou « veuillez ».'),


  Exercise(id:'ce1_me1',lessonId:'ce1_ml1',question:'Dans 482, quel chiffre représente les dizaines ?',options:['4','8','2'],correctIndex:1,explanation:'Dans 482, 4 représente les centaines, 8 les dizaines et 2 les unités.'),
  Exercise(id:'ce1_me2',lessonId:'ce1_ml2',question:'Afi a 12 mangues et en reçoit 5 autres. Quelle opération faut-il faire ?',options:['12 + 5','12 − 5','12 × 5'],correctIndex:0,explanation:'On réunit 12 mangues et 5 mangues : 12 + 5 = 17.'),
  Exercise(id:'ce1_fe1',lessonId:'ce1_fl1',question:'Dans « une école », quel mot est le déterminant ?',options:['école','une','aucun'],correctIndex:1,explanation:'« une » accompagne le nom « école » : c’est le déterminant.'),
  Exercise(id:'ce1_fe2',lessonId:'ce1_fl2',question:'Que faut-il repérer pour comprendre un récit ?',options:['Les personnages et les événements','Seulement le nombre de lignes','La couleur des pages'],correctIndex:0,explanation:'Les personnages, le lieu et les événements permettent de comprendre l’histoire.'),
  Exercise(id:'ce1_ee1',lessonId:'ce1_el1',question:'Quelle partie de la plante absorbe souvent l’eau du sol ?',options:['La fleur','Les racines','Le fruit'],correctIndex:1,explanation:'Les racines absorbent l’eau et fixent généralement la plante dans le sol.'),
  Exercise(id:'ce1_ee2',lessonId:'ce1_el2',question:'Quel comportement respecte les animaux ?',options:['Détruire leur abri','Les blesser','Protéger leur milieu de vie'],correctIndex:2,explanation:'Protéger leur habitat permet aux animaux de vivre dans de bonnes conditions.'),
  Exercise(id:'ce1_ae1',lessonId:'ce1_al1',question:'What does “My name is Kossi” mean?',options:['Je m’appelle Kossi','J’ai huit ans','Au revoir Kossi'],correctIndex:0,explanation:'“My name is Kossi” signifie « Je m’appelle Kossi ».'),
  Exercise(id:'ce1_ae2',lessonId:'ce1_al2',question:'What does “Listen” mean?',options:['Écris','Écoute','Lis'],correctIndex:1,explanation:'“Listen” signifie « Écoute ».'),

  Exercise(id:'ce2_me1',lessonId:'ce2_ml1',question:'Quelle est la décomposition correcte de 3 624 ?',options:['3 000 + 600 + 20 + 4','300 + 60 + 2 + 4','3 000 + 60 + 24'],correctIndex:0,explanation:'3 624 contient 3 milliers, 6 centaines, 2 dizaines et 4 unités.'),
  Exercise(id:'ce2_me2',lessonId:'ce2_ml2',question:'24 bonbons sont partagés également entre 6 enfants. Combien chaque enfant reçoit-il ?',options:['3','4','6'],correctIndex:1,explanation:'24 ÷ 6 = 4 bonbons par enfant.'),
  Exercise(id:'ce2_me3',lessonId:'ce2_ml3',question:'Combien de centimètres y a-t-il dans 2 mètres ?',options:['20 cm','200 cm','2 000 cm'],correctIndex:1,explanation:'1 m = 100 cm, donc 2 m = 2 × 100 = 200 cm.'),
  Exercise(id:'ce2_me4',lessonId:'ce2_ml3',question:'Un rectangle mesure 5 cm de long et 2 cm de large. Quel est son périmètre ?',options:['7 cm','10 cm','14 cm'],correctIndex:2,explanation:'P = 5 + 2 + 5 + 2 = 14 cm.'),
  Exercise(id:'ce2_me5',lessonId:'ce2_ml3',question:'Quel instrument convient pour mesurer la longueur d’un cahier ?',options:['Une règle graduée','Une balance','Un thermomètre'],correctIndex:0,explanation:'Une règle graduée permet de mesurer la longueur d’un cahier en centimètres.'),
  Exercise(id:'ce2_me6',lessonId:'ce2_ml3',question:'Le périmètre d’une figure correspond à…',options:['La couleur de la figure','La longueur de son contour','Son poids'],correctIndex:1,explanation:'Le périmètre est la somme des longueurs de tous les côtés du contour.'),
  Exercise(id:'ce2_fe1',lessonId:'ce2_fl1',question:'Complète : « Nous ___ à l’école. »',options:['sommes','êtes','sont'],correctIndex:0,explanation:'Avec le sujet « nous », le verbe être se conjugue « nous sommes ».'),
  Exercise(id:'ce2_fe2',lessonId:'ce2_fl2',question:'Quel mot peut annoncer la dernière étape d’un récit ?',options:['D’abord','Ensuite','Enfin'],correctIndex:2,explanation:'« Enfin » annonce généralement la dernière étape.'),
  Exercise(id:'ce2_fe3',lessonId:'ce2_fl3',question:'Complète : « une robe ___ »',options:['bleu','bleue','bleus'],correctIndex:1,explanation:'« Robe » est féminin singulier : on écrit « une robe bleue ».'),
  Exercise(id:'ce2_fe4',lessonId:'ce2_fl3',question:'Choisis le bon accord : « des garçons ___ »',options:['sage','sages','sagesse'],correctIndex:1,explanation:'« Garçons » est masculin pluriel : l’adjectif prend ici un -s, « sages ».'),
  Exercise(id:'ce2_fe5',lessonId:'ce2_fl3',question:'Dans « une petite maison », quel mot est l’adjectif ?',options:['une','petite','maison'],correctIndex:1,explanation:'« Petite » donne une précision sur le nom « maison » : c’est l’adjectif.'),
  Exercise(id:'ce2_fe6',lessonId:'ce2_fl3',question:'Quel groupe nominal est correctement écrit ?',options:['des fleur rouge','des fleurs rouges','des fleurs rouge'],correctIndex:1,explanation:'« Fleurs » est féminin pluriel : l’adjectif s’accorde au féminin pluriel, « rouges ».'),
  Exercise(id:'ce2_ae3',lessonId:'ce2_al3',question:'What does “I wake up” mean?',options:['Je me réveille','Je me couche','Je joue'],correctIndex:0,explanation:'“I wake up” signifie « je me réveille ».'),
  Exercise(id:'ce2_ae4',lessonId:'ce2_al3',question:'Choose the correct sentence: « Je vais à l’école. »',options:['I go to school.','I eat breakfast.','I go to bed.'],correctIndex:0,explanation:'“I go to school” signifie « je vais à l’école ».'),
  Exercise(id:'ce2_ae5',lessonId:'ce2_al3',question:'What does “I go to bed” mean?',options:['Je lis','Je vais me coucher','Je me lave'],correctIndex:1,explanation:'“I go to bed” signifie « je vais me coucher ».'),
  Exercise(id:'ce2_ae6',lessonId:'ce2_al3',question:'Which action usually comes before going to school?',options:['I wake up','I go to bed','I sleep at school'],correctIndex:0,explanation:'On se réveille généralement avant de partir à l’école.'),
  Exercise(id:'ce2_ee1',lessonId:'ce2_el1',question:'Comment appelle-t-on l’eau à l’état solide ?',options:['Vapeur','Glace','Pluie'],correctIndex:1,explanation:'À l’état solide, l’eau forme de la glace.'),
  Exercise(id:'ce2_ee2',lessonId:'ce2_el2',question:'Quel geste protège l’environnement ?',options:['Jeter les déchets dans la rivière','Brûler les plastiques près des maisons','Utiliser une poubelle'],correctIndex:2,explanation:'Mettre les déchets dans une poubelle évite de salir le milieu.'),
  Exercise(id:'ce2_ae1',lessonId:'ce2_al1',question:'What colour is “green”?',options:['Rouge','Vert','Jaune'],correctIndex:1,explanation:'“Green” signifie « vert ».'),
  Exercise(id:'ce2_ae2',lessonId:'ce2_al2',question:'What does “sister” mean?',options:['Sœur','Mère','Frère'],correctIndex:0,explanation:'“Sister” signifie « sœur ».'),

  Exercise(id:'cm1_es_dechets',lessonId:'cm1_es_lecon1',question:'Où faut-il déposer les déchets ménagers ?',options:['Dans les caniveaux','Dans une poubelle ou un lieu de collecte prévu','Dans la rue'],correctIndex:1,explanation:'Les déchets doivent être déposés dans les espaces de collecte pour éviter la pollution et l’obstruction des caniveaux.'),
  Exercise(id:'cm1_es_eau',lessonId:'cm1_es_lecon1',question:'Quel geste permet d’économiser l’eau ?',options:['Laisser le robinet ouvert','Réparer ou signaler une fuite et fermer le robinet après usage','Jeter les déchets dans l’eau'],correctIndex:1,explanation:'Fermer le robinet et signaler les fuites évitent le gaspillage de l’eau.'),
  Exercise(id:'cm1_es_solidaire',lessonId:'cm1_es_lecon1',question:'Quelle action montre la solidarité dans le quartier ?',options:['Aider à une action collective de nettoyage avec les adultes','Détériorer un banc public','Empêcher les autres de participer'],correctIndex:0,explanation:'Participer à une action collective et respecter les biens communs sont des gestes citoyens.'),
  Exercise(id:'cm1_es_caniveau',lessonId:'cm1_es_lecon1',question:'Pourquoi ne faut-il pas jeter les déchets dans les caniveaux ?',options:['Pour faciliter les inondations','Parce qu’ils peuvent boucher l’écoulement de l’eau','Pour attirer les moustiques'],correctIndex:1,explanation:'Les déchets peuvent bloquer l’écoulement des eaux et favoriser les inondations.'),
  Exercise(id:'cm1_me1',lessonId:'cm1_ml1',question:'Dans la fraction 2/5, que représente le chiffre 5 ?',options:['Le nombre de parts prises','Le nombre de parts égales de l’unité','La valeur de l’unité'],correctIndex:1,explanation:'Le dénominateur 5 indique que l’unité est partagée en cinq parts égales.'),
  Exercise(id:'cm1_me2',lessonId:'cm1_ml2',question:'Combien vaut 42 ÷ 7 ?',options:['5','6','7'],correctIndex:1,explanation:'42 ÷ 7 = 6 car 7 × 6 = 42.'),
  Exercise(id:'cm1_me3',lessonId:'cm1_ml3',question:'Un rectangle mesure 7 cm de long et 4 cm de large. Quel est son périmètre ?',options:['11 cm','22 cm','28 cm'],correctIndex:1,explanation:'P = 2 × (7 + 4) = 22 cm.'),
  Exercise(id:'cm1_me4',lessonId:'cm1_ml3',question:'Quelle est l’aire d’un rectangle de 6 cm sur 5 cm ?',options:['11 cm²','22 cm²','30 cm²'],correctIndex:2,explanation:'A = longueur × largeur = 6 × 5 = 30 cm².'),
  Exercise(id:'cm1_me5',lessonId:'cm1_ml3',question:'Quelle unité convient pour exprimer une aire ?',options:['cm','cm²','kg'],correctIndex:1,explanation:'Une aire s’exprime en unités carrées, par exemple cm².'),
  Exercise(id:'cm1_me6',lessonId:'cm1_ml3',question:'Le périmètre d’une figure représente…',options:['Sa surface intérieure','La longueur de son contour','Sa masse'],correctIndex:1,explanation:'Le périmètre est la longueur totale du contour de la figure.'),
  Exercise(id:'cm1_fe1',lessonId:'cm1_fl1',question:'Dans « Les enfants jouent », quel est le sujet ?',options:['jouent','Les enfants','enfants jouent'],correctIndex:1,explanation:'« Les enfants » est le groupe sujet du verbe « jouent ».'),
  Exercise(id:'cm1_fe2',lessonId:'cm1_fl2',question:'Quel temps indique le mot « demain » ?',options:['Le passé','Le présent','Le futur'],correctIndex:2,explanation:'« Demain » annonce un moment à venir : le futur.'),
  Exercise(id:'cm1_se1',lessonId:'cm1_sl1',question:'Quel organe fait circuler le sang ?',options:['Le cœur','L’estomac','Les poumons'],correctIndex:0,explanation:'Le cœur agit comme une pompe et fait circuler le sang.'),
  Exercise(id:'cm1_se2',lessonId:'cm1_sl2',question:'Quelle propriété correspond à un liquide ?',options:['Il conserve toujours sa forme','Il prend la forme du récipient','Il occupe tout l’espace comme un gaz'],correctIndex:1,explanation:'Un liquide s’écoule et prend la forme du récipient qui le contient.'),
  Exercise(id:'cm1_se3',lessonId:'cm1_sl3',question:'Quels éléments peuvent former un circuit simple pour allumer une petite lampe ?',options:['Une pile, des fils et une lampe adaptée','Une feuille et un crayon','De l’eau et du sable'],correctIndex:0,explanation:'Une pile fournit l’énergie, les fils relient les éléments et la lampe adaptée s’allume si le circuit est fermé.'),
  Exercise(id:'cm1_se4',lessonId:'cm1_sl3',question:'Que se passe-t-il si le circuit est ouvert ?',options:['La lampe s’allume plus fort','La lampe ne s’allume pas','La pile devient une lampe'],correctIndex:1,explanation:'Un circuit ouvert ne forme pas une boucle complète : le courant ne circule pas.'),
  Exercise(id:'cm1_se5',lessonId:'cm1_sl3',question:'Lequel de ces matériaux est généralement conducteur ?',options:['Le plastique','Le métal','Le bois sec'],correctIndex:1,explanation:'Les métaux conduisent généralement l’électricité, contrairement au plastique et au bois sec.'),
  Exercise(id:'cm1_se6',lessonId:'cm1_sl3',question:'Quelle règle de sécurité faut-il respecter ?',options:['Démonter une prise murale','Toucher les fils du secteur','Utiliser du matériel scolaire à basse tension avec un adulte'],correctIndex:2,explanation:'Les élèves doivent utiliser uniquement du matériel scolaire à basse tension, sous la surveillance d’un adulte.'),
  Exercise(id:'cm1_ae1',lessonId:'cm1_al1',question:'What does “I go to school” mean?',options:['Je vais à l’école','Je mange','Je dors'],correctIndex:0,explanation:'“I go to school” signifie « Je vais à l’école ».'),
  Exercise(id:'cm1_ae2',lessonId:'cm1_al2',question:'How do you say 7:00 in English?',options:['Half past seven','Seven o’clock','Six o’clock'],correctIndex:1,explanation:'7:00 se dit “seven o’clock”.'),

  Exercise(id:'cm2_she1',lessonId:'cm2_shl1',question:'Dans quelle partie du continent africain se trouve le Togo ?',options:['Afrique de l’Est','Afrique de l’Ouest','Afrique australe'],correctIndex:1,explanation:'Le Togo est un pays d’Afrique de l’Ouest.'),
  Exercise(id:'cm2_shl2_e1',lessonId:'cm2_shl2',question:'Laquelle de ces activités est une activité agricole ?',options:['La culture du maïs','La conduite d’un avion','La vente d’un billet de cinéma'],correctIndex:0,explanation:'Cultiver le maïs est une activité agricole.'),
  Exercise(id:'cm2_shl2_e2',lessonId:'cm2_shl2',question:'Quel moyen de transport est utilisé pour transporter des marchandises par mer ?',options:['Le camion','Le bateau','Le vélo'],correctIndex:1,explanation:'Le bateau est un moyen de transport maritime.'),
  Exercise(id:'cm2_shl2_e3',lessonId:'cm2_shl2',question:'Quel équipement facilite les échanges maritimes au Togo ?',options:['Le port de Lomé','Une gare routière de village','Un terrain de sport'],correctIndex:0,explanation:'Le port autonome de Lomé facilite le transport maritime et les échanges.'),
  Exercise(id:'cm2_shl2_e4',lessonId:'cm2_shl2',question:'Que faut-il prendre en compte pour choisir un transport ?',options:['Seulement la couleur du véhicule','Le coût, la distance et la sécurité','Uniquement le nom du conducteur'],correctIndex:1,explanation:'Le choix tient compte du coût, de la distance, du délai et de la sécurité.'),
  Exercise(id:'cm2_she2',lessonId:'cm2_shl1',question:'Quel pays se trouve à l’ouest du Togo ?',options:['Le Ghana','Le Bénin','Le Nigeria'],correctIndex:0,explanation:'Le Ghana partage la frontière occidentale du Togo.'),
  Exercise(id:'cm2_she3',lessonId:'cm2_shl1',question:'Quelle est la capitale du Togo ?',options:['Kara','Atakpamé','Lomé'],correctIndex:2,explanation:'Lomé est la capitale du Togo et se trouve au sud du pays.'),
  Exercise(id:'cm2_she4',lessonId:'cm2_shl1',question:'Combien de régions administratives compte le Togo ?',options:['Trois','Cinq','Sept'],correctIndex:1,explanation:'Le Togo compte cinq régions administratives : Maritime, Plateaux, Centrale, Kara et Savanes.'),
  Exercise(id:'cm2_me1',lessonId:'cm2_ml1',question:'Calcule : 12,50 + 3,25.',options:['15,75','15,25','16,75'],correctIndex:0,explanation:'En alignant les virgules : 12,50 + 3,25 = 15,75.'),
  Exercise(id:'cm2_me2',lessonId:'cm2_ml2',question:'Quelle est l’aire d’un rectangle de 8 cm sur 3 cm ?',options:['11 cm²','22 cm²','24 cm²'],correctIndex:2,explanation:'A = longueur × largeur = 8 × 3 = 24 cm².'),
  Exercise(id:'cm2_me3',lessonId:'cm2_ml3',question:'24 mangues sont partagées également entre 6 enfants. Combien chaque enfant reçoit-il ?',options:['3 mangues','4 mangues','6 mangues'],correctIndex:1,explanation:'24 ÷ 6 = 4. Chaque enfant reçoit 4 mangues.'),
  Exercise(id:'cm2_me4',lessonId:'cm2_ml3',question:'Un cahier coûte 250 F. Combien coûtent 3 cahiers ?',options:['500 F','650 F','750 F'],correctIndex:2,explanation:'250 × 3 = 750 F.'),
  Exercise(id:'cm2_me5',lessonId:'cm2_ml3',question:'Awa possède 2 000 F. Elle achète un livre à 1 250 F. Combien lui reste-t-il ?',options:['650 F','750 F','850 F'],correctIndex:1,explanation:'2 000 − 1 250 = 750 F.'),
  Exercise(id:'cm2_me6',lessonId:'cm2_ml3',question:'Pour partager 36 crayons en 4 lots égaux, quelle opération faut-il effectuer ?',options:['36 + 4','36 × 4','36 ÷ 4'],correctIndex:2,explanation:'Un partage en lots égaux se calcule par une division : 36 ÷ 4 = 9 crayons par lot.'),
  Exercise(id:'cm2_ml4_addition',lessonId:'cm2_ml4',question:'Calcule mentalement 48 + 27.',options:['65','75','85'],correctIndex:1,explanation:'48 + 2 = 50, puis 25 de plus : 75.'),
  Exercise(id:'cm2_ml4_subtraction',lessonId:'cm2_ml4',question:'Calcule 600 − 198 en utilisant un nombre proche.',options:['402','412','498'],correctIndex:0,explanation:'600 − 200 = 400, puis on ajoute 2 : 402.'),
  Exercise(id:'cm2_ml4_multiply5',lessonId:'cm2_ml4',question:'Combien font 36 × 5 ?',options:['160','180','200'],correctIndex:1,explanation:'36 × 10 = 360, puis 360 ÷ 2 = 180.'),
  Exercise(id:'cm2_ml4_multiply9',lessonId:'cm2_ml4',question:'Combien font 8 × 9 ?',options:['64','72','81'],correctIndex:1,explanation:'8 × 10 = 80, puis 80 − 8 = 72.'),
  Exercise(id:'cm2_fe3',lessonId:'cm2_fl3',question:'Quelle formule peut commencer une lettre personnelle adressée à une amie ?',options:['Chère Afi,','Madame le directeur,','Fin de la lettre'],correctIndex:0,explanation:'« Chère Afi » est une formule d’appel adaptée à une amie.'),
  Exercise(id:'cm2_fe4',lessonId:'cm2_fl3',question:'Où place-t-on généralement le message principal ?',options:['Dans le corps de la lettre','Dans la signature','Avant le lieu et la date'],correctIndex:0,explanation:'Le corps de la lettre contient les informations et le message.'),
  Exercise(id:'cm2_fe5',lessonId:'cm2_fl3',question:'Que faut-il faire avant de recopier définitivement sa lettre ?',options:['Supprimer la ponctuation','Relire et corriger','Oublier le sujet'],correctIndex:1,explanation:'La relecture permet de corriger les erreurs et de vérifier les consignes.'),
  Exercise(id:'cm2_fe6',lessonId:'cm2_fl3',question:'Quel élément termine une lettre personnelle ?',options:['Une formule de politesse et une signature','Une nouvelle introduction','La liste des questions'],correctIndex:0,explanation:'On termine par une formule de politesse puis sa signature.'),
  Exercise(id:'cm2_fe7',lessonId:'cm2_fl4',question:'Dans une dictée, que faut-il vérifier en priorité après avoir écrit ?',options:['Les accords, les verbes et la ponctuation','La couleur du cahier','Le nombre de lignes seulement'],correctIndex:0,explanation:'La relecture vérifie notamment les accords, les terminaisons verbales, les majuscules et la ponctuation.'),
  Exercise(id:'cm2_fe8',lessonId:'cm2_fl4',question:'Dans « les élèves ont nettoyé la cour », pourquoi écrit-on « ont » avec -ont ?',options:['Parce que le sujet « les élèves » est au pluriel','Parce que le mot est au féminin','Parce que la phrase est une question'],correctIndex:0,explanation:'Le sujet « les élèves » est à la troisième personne du pluriel : on écrit « ils ont ».'),
  Exercise(id:'cm2_fl5_questions1',lessonId:'cm2_fl5',question:'Une question qui commence par « où » demande généralement…',options:['Un lieu','Une personne','Une date'],correctIndex:0,explanation:'« Où » sert à demander le lieu.'),
  Exercise(id:'cm2_fl5_questions2',lessonId:'cm2_fl5',question:'Quelle est la meilleure manière de répondre à une question de compréhension ?',options:['Par une phrase claire appuyée sur le texte','En inventant une information','En recopiant tout le texte'],correctIndex:0,explanation:'Une réponse précise doit être justifiée par les informations du texte.'),
  Exercise(id:'cm2_fl5_questions3',lessonId:'cm2_fl5',question:'Que faut-il faire après une première lecture ?',options:['Relire pour repérer les informations utiles','Fermer le livre sans réfléchir','Répondre au hasard'],correctIndex:0,explanation:'La relecture aide à retrouver les détails nécessaires pour répondre.'),
  Exercise(id:'cm2_fl5_questions4',lessonId:'cm2_fl5',question:'Une question qui commence par « pourquoi » demande…',options:['Une raison','Un lieu','Un nombre seulement'],correctIndex:0,explanation:'« Pourquoi » demande la cause ou la raison d’un fait.'),
  Exercise(id:'cm2_se3',lessonId:'cm2_sl3',question:'Lequel est un milieu de vie ?',options:['Une mare','Un cahier','Une règle'],correctIndex:0,explanation:'Une mare est un milieu de vie où des plantes et des animaux peuvent vivre.'),
  Exercise(id:'cm2_se4',lessonId:'cm2_sl3',question:'Quel geste protège l’environnement ?',options:['Jeter les plastiques dans la rivière','Brûler les déchets près des maisons','Planter des arbres et garder les lieux propres'],correctIndex:2,explanation:'Planter des arbres et éviter les déchets abandonnés contribuent à protéger l’environnement.'),
  Exercise(id:'cm2_se5',lessonId:'cm2_sl3',question:'De quoi les plantes ont-elles notamment besoin pour grandir ?',options:['D’eau et de lumière','De plastique','De fumée'],correctIndex:0,explanation:'Les plantes ont notamment besoin d’eau, d’air et de lumière.'),
  Exercise(id:'cm2_se6',lessonId:'cm2_sl3',question:'Quelle conséquence peut avoir la pollution d’une mare ?',options:['Elle améliore toujours la santé des animaux','Elle peut menacer les êtres vivants','Elle transforme l’eau en eau potable'],correctIndex:1,explanation:'La pollution peut rendre le milieu dangereux pour les plantes et les animaux.'),
  Exercise(id:'cm2_sl4_states',lessonId:'cm2_sl4',question:'Quel est l’état de l’eau dans la glace ?',options:['Solide','Liquide','Gazeux'],correctIndex:0,explanation:'La glace est de l’eau à l’état solide.'),
  Exercise(id:'cm2_sl4_evap',lessonId:'cm2_sl4',question:'Comment appelle-t-on le passage de l’eau liquide en vapeur ?',options:['Condensation','Évaporation','Solidification'],correctIndex:1,explanation:'L’évaporation transforme l’eau liquide en vapeur sous l’effet de la chaleur.'),
  Exercise(id:'cm2_sl4_cloud',lessonId:'cm2_sl4',question:'La formation des gouttelettes qui constituent les nuages correspond à…',options:['La condensation','La combustion','La fusion du métal'],correctIndex:0,explanation:'La vapeur d’eau se refroidit et se condense en fines gouttelettes.'),
  Exercise(id:'cm2_sl4_protect',lessonId:'cm2_sl4',question:'Quel geste protège une source d’eau ?',options:['Y jeter des déchets','Y verser de l’huile','Éviter de la polluer et économiser l’eau'],correctIndex:2,explanation:'Ne pas polluer les sources et éviter le gaspillage préservent l’eau.'),
  Exercise(id:'cm2_fe1',lessonId:'cm2_fl1',question:'Quelle expression est correctement accordée ?',options:['Des jolie fleurs','Des jolies fleurs','Des joli fleurs'],correctIndex:1,explanation:'« Fleurs » est féminin pluriel : on écrit « des jolies fleurs ».'),
  Exercise(id:'cm2_fe2',lessonId:'cm2_fl2',question:'Quelle partie termine généralement un texte organisé ?',options:['La conclusion','Le titre','L’introduction'],correctIndex:0,explanation:'La conclusion termine le texte et rappelle l’idée essentielle.'),
  Exercise(id:'cm2_se1',lessonId:'cm2_sl1',question:'Laquelle est une source d’énergie renouvelable ?',options:['Le charbon','Le pétrole','Le vent'],correctIndex:2,explanation:'Le vent est une source renouvelable d’énergie.'),
  Exercise(id:'cm2_se2',lessonId:'cm2_sl2',question:'Quel geste aide à prévenir certaines maladies ?',options:['Boire de l’eau non potable','Se laver les mains au savon','Partager une serviette sale'],correctIndex:1,explanation:'Le lavage des mains avec de l’eau propre et du savon aide à limiter la transmission de microbes.'),
  Exercise(id:'cm2_ae1',lessonId:'cm2_al1',question:'What does “Turn left” mean?',options:['Tourne à droite','Va tout droit','Tourne à gauche'],correctIndex:2,explanation:'“Turn left” signifie « Tourne à gauche ».'),
  Exercise(id:'cm2_ae2',lessonId:'cm2_al2',question:'What does “yesterday” mean?',options:['Demain','Hier','Aujourd’hui'],correctIndex:1,explanation:'“Yesterday” signifie « hier ».'),
  Exercise(id:'cinq_me1',lessonId:'cinq_ml1',question:'Quel nombre est le plus grand ?',options:['-7','-2','-9'],correctIndex:1,explanation:'-2 est le plus grand : il est le plus proche de zéro parmi ces nombres négatifs.'),
  Exercise(id:'cinq_me2',lessonId:'cinq_ml2',question:'Quelle fraction est équivalente à 2/4 ?',options:['1/2','1/4','2/3'],correctIndex:0,explanation:'En divisant le numérateur et le dénominateur par 2, on obtient 1/2.'),
  Exercise(id:'cinq_fe1',lessonId:'cinq_fl1',question:'Quel élément indique où se déroule l’histoire ?',options:['Le lieu','Le titre seulement','La ponctuation'],correctIndex:0,explanation:'Le lieu précise l’endroit où se déroulent les événements.'),
  Exercise(id:'cinq_fe2',lessonId:'cinq_fl2',question:'Dans « une belle maison », quel mot est l’adjectif ?',options:['une','belle','maison'],correctIndex:1,explanation:'« Belle » qualifie le nom « maison » : c’est un adjectif.'),
  Exercise(id:'cinq_se1',lessonId:'cinq_sl1',question:'Pourquoi faut-il varier son alimentation ?',options:['Pour couvrir les besoins du corps','Pour ne manger qu’un seul aliment','Pour éviter de boire'],correctIndex:0,explanation:'Les différents aliments apportent des nutriments et de l’énergie complémentaires.'),
  Exercise(id:'cinq_se2',lessonId:'cinq_sl2',question:'Quel geste limite la transmission de microbes ?',options:['Partager une bouteille','Se laver les mains au savon','Boire de l’eau non potable'],correctIndex:1,explanation:'Le lavage des mains au savon aide à éliminer les microbes.'),
  Exercise(id:'cinq_ae1',lessonId:'cinq_al1',question:'Choose the correct sentence.',options:['She go to school.','She goes to school.','She going school.'],correctIndex:1,explanation:'À la troisième personne du singulier au présent simple, on ajoute généralement -s au verbe.'),
  Exercise(id:'cinq_ae2',lessonId:'cinq_al2',question:'What does “tall” mean?',options:['Petit','Grand','Rapide'],correctIndex:1,explanation:'“Tall” signifie « grand » pour parler de la taille d’une personne.'),
  Exercise(id:'quatre_me1',lessonId:'quatre_ml1',question:'Développer 4(x + 3) donne :',options:['4x + 3','4x + 12','x + 12'],correctIndex:1,explanation:'On multiplie 4 par chaque terme : 4 × x + 4 × 3 = 4x + 12.'),
  Exercise(id:'quatre_me2',lessonId:'quatre_ml2',question:'Combien représentent 20 % de 150 ?',options:['15','20','30'],correctIndex:2,explanation:'150 × 20/100 = 30.'),
  Exercise(id:'quatre_fe1',lessonId:'quatre_fl1',question:'Quel élément défend le point de vue dans un texte argumentatif ?',options:['La thèse','La liste des personnages','La ponctuation seule'],correctIndex:0,explanation:'La thèse est la position ou l’opinion défendue.'),
  Exercise(id:'quatre_fe2',lessonId:'quatre_fl2',question:'Une phrase contenant deux verbes conjugués contient généralement :',options:['Deux propositions','Aucune proposition','Une syllabe'],correctIndex:0,explanation:'Chaque proposition est organisée autour d’un verbe conjugué.'),
  Exercise(id:'quatre_se1',lessonId:'quatre_sl1',question:'Quel est le rôle principal de la reproduction ?',options:['Assurer la continuité des espèces','Faire disparaître les espèces','Produire uniquement de l’énergie'],correctIndex:0,explanation:'La reproduction permet aux espèces de se maintenir au fil des générations.'),
  Exercise(id:'quatre_se2',lessonId:'quatre_sl2',question:'Qu’est-ce qu’un écosystème ?',options:['Uniquement un animal','Un milieu et les êtres vivants qui y interagissent','Une machine'],correctIndex:1,explanation:'Un écosystème comprend un milieu de vie et les organismes qui y vivent et interagissent.'),
  Exercise(id:'quatre_ae1',lessonId:'quatre_al1',question:'Choose the correct past form of “go”.',options:['goed','went','goes'],correctIndex:1,explanation:'“Went” est le prétérit irrégulier du verbe “go”.'),
  Exercise(id:'quatre_ae2',lessonId:'quatre_al2',question:'Which sentence expresses a planned intention?',options:['I am going to study.','I studied yesterday.','I study every day.'],correctIndex:0,explanation:'“Be going to” sert à exprimer un projet ou une intention.'),

  Exercise(id:'trois_me1',lessonId:'trois_ml1',question:'Un triangle rectangle a des côtés de l’angle droit de 6 cm et 8 cm. Quelle est son hypoténuse ?',options:['10 cm','12 cm','14 cm'],correctIndex:0,explanation:'BC² = 6² + 8² = 36 + 64 = 100, donc BC = 10 cm.'),
  Exercise(id:'trois_me2',lessonId:'trois_ml2',question:'Quelle est la solution de 2x + 7 = 19 ?',options:['5','6','7'],correctIndex:1,explanation:'2x = 19 − 7 = 12, donc x = 12 ÷ 2 = 6.'),
  Exercise(id:'trois_fe1',lessonId:'trois_fl1',question:'Dans un texte argumentatif, que désigne la thèse ?',options:['Le point de vue défendu','Le nom de l’auteur','La liste des personnages'],correctIndex:0,explanation:'La thèse est l’opinion ou la position que l’auteur cherche à défendre.'),
  Exercise(id:'trois_fe2',lessonId:'trois_fl2',question:'Dans « Je sais que tu viendras », quelle partie est la subordonnée ?',options:['Je sais','que tu viendras','Je sais que'],correctIndex:1,explanation:'« que tu viendras » dépend de la principale « Je sais ».'),
  Exercise(id:'trois_se1',lessonId:'trois_sl1',question:'Quelle molécule porte l’information héréditaire ?',options:['L’ADN','L’eau','Le glucose'],correctIndex:0,explanation:'L’ADN porte l’information génétique transmise entre générations.'),
  Exercise(id:'trois_se2',lessonId:'trois_sl2',question:'Lequel peut perturber un écosystème ?',options:['La protection des habitats','La pollution de l’eau','La restauration des sols'],correctIndex:1,explanation:'La pollution de l’eau peut nuire aux organismes et déséquilibrer le milieu.'),
  Exercise(id:'trois_ae1',lessonId:'trois_al1',question:'Choose the correct past form: “Yesterday, I ___ to school.”',options:['go','went','going'],correctIndex:1,explanation:'“Went” est le prétérit irrégulier du verbe “go”.'),
  Exercise(id:'trois_ae2',lessonId:'trois_al2',question:'Complete: “She ___ going to study tonight.”',options:['am','are','is'],correctIndex:2,explanation:'Avec “she”, on utilise “is”: She is going to study tonight.'),

  Exercise(id:'seconde_me1',lessonId:'seconde_ml1',question:'Si f(x) = 3x − 2, quelle est l’image de 5 ?',options:['13','15','17'],correctIndex:0,explanation:'f(5) = 3 × 5 − 2 = 15 − 2 = 13.'),
  Exercise(id:'seconde_me2',lessonId:'seconde_ml2',question:'Quelle est la forme développée de 2(x + 5) ?',options:['2x + 5','2x + 10','x + 10'],correctIndex:1,explanation:'On distribue 2 : 2 × x + 2 × 5 = 2x + 10.'),
  Exercise(id:'seconde_fe1',lessonId:'seconde_fl1',question:'Dans une analyse littéraire, à quoi sert une citation ?',options:['À appuyer une interprétation du texte','À remplacer toute explication','À décorer le devoir'],correctIndex:0,explanation:'Une citation apporte une preuve textuelle qui doit être expliquée.'),
  Exercise(id:'seconde_fe2',lessonId:'seconde_fl2',question:'Quel élément justifie une idée dans un paragraphe argumenté ?',options:['Un argument','Une signature','Un titre sans rapport'],correctIndex:0,explanation:'L’argument donne une raison qui soutient l’idée directrice.'),
  Exercise(id:'seconde_se1',lessonId:'seconde_sl1',question:'Quelle structure délimite la cellule ?',options:['La membrane','Le chromosome seul','Le squelette'],correctIndex:0,explanation:'La membrane cellulaire délimite la cellule et contrôle les échanges.'),
  Exercise(id:'seconde_se2',lessonId:'seconde_sl2',question:'Sur quoi repose principalement une classification scientifique ?',options:['Les caractères partagés et les liens de parenté','La taille uniquement','La couleur uniquement'],correctIndex:0,explanation:'La classification scientifique compare les caractères partagés et les relations de parenté.'),
  Exercise(id:'seconde_ae1',lessonId:'seconde_al1',question:'Which expression introduces an opinion?',options:['In my opinion…','Good night…','See you later…'],correctIndex:0,explanation:'“In my opinion” signifie « À mon avis » et introduit un point de vue.'),
  Exercise(id:'seconde_ae2',lessonId:'seconde_al2',question:'Choose the correct sentence for an action in progress in the past.',options:['I read now.','I was reading when he called.','I will read tomorrow.'],correctIndex:1,explanation:'Le past continuous “was reading” décrit une action en cours dans le passé.'),

  Exercise(id:'premiere_me1',lessonId:'premiere_ml1',question:'Une suite est définie par u(n) = 3n + 2. Quelle est la valeur de u(4) ?',options:['12','14','18'],correctIndex:1,explanation:'u(4) = 3 × 4 + 2 = 14.'),
  Exercise(id:'premiere_me2',lessonId:'premiere_ml2',question:'Si f’(x) est positive sur un intervalle, que peut-on conclure ?',options:['f est croissante','f est décroissante','f est constante obligatoirement'],correctIndex:0,explanation:'Une dérivée positive sur un intervalle indique que la fonction y est croissante.'),
  Exercise(id:'premiere_fe1',lessonId:'premiere_fl1',question:'Que doit-on faire après avoir identifié une métaphore ?',options:['Expliquer son effet et son sens','Ignorer le contexte','Compter uniquement les syllabes'],correctIndex:0,explanation:'L’analyse doit interpréter l’image et expliquer ce qu’elle apporte au texte.'),
  Exercise(id:'premiere_fe2',lessonId:'premiere_fl2',question:'Quel est le rôle principal de la problématique dans une dissertation ?',options:['Poser la question directrice de la réflexion','Remplacer la conclusion','Donner la biographie de l’auteur'],correctIndex:0,explanation:'La problématique organise la réflexion et guide le plan de la dissertation.'),
  Exercise(id:'premiere_se1',lessonId:'premiere_sl1',question:'Qu’est-ce qu’un gène ?',options:['Une portion d’ADN','Un organe','Une cellule entière'],correctIndex:0,explanation:'Un gène est une portion d’ADN portant une information génétique.'),
  Exercise(id:'premiere_se2',lessonId:'premiere_sl2',question:'Quelle cellule peut produire des anticorps ?',options:['Un lymphocyte B différencié en plasmocyte','Un globule rouge','Une cellule de peau'],correctIndex:0,explanation:'Les plasmocytes issus des lymphocytes B sécrètent des anticorps.'),
  Exercise(id:'premiere_ae1',lessonId:'premiere_al1',question:'Which expression introduces a personal opinion?',options:['In my view…','At the station…','Last Monday…'],correctIndex:0,explanation:'“In my view” signifie « À mon avis ».'),
  Exercise(id:'premiere_ae2',lessonId:'premiere_al2',question:'Which closing is suitable for a formal email when the recipient is unknown?',options:['See ya!','Yours faithfully,','What’s up?'],correctIndex:1,explanation:'“Yours faithfully” est une formule de politesse adaptée lorsque le destinataire est inconnu.'),

  Exercise(id:'terminale_me1',lessonId:'terminale_ml1',question:'Quelle est la limite de f(x) = 1/x lorsque x tend vers +∞ ?',options:['0','1','+∞'],correctIndex:0,explanation:'Lorsque x devient très grand et positif, 1/x se rapproche de 0.'),
  Exercise(id:'terminale_me2',lessonId:'terminale_ml2',question:'Si P(B)=0,4 et P(A ∩ B)=0,2, quelle est P(A sachant B) ?',options:['0,2','0,5','0,8'],correctIndex:1,explanation:'P(A|B) = 0,2 ÷ 0,4 = 0,5.'),
  Exercise(id:'terminale_fe1',lessonId:'terminale_fl1',question:'Quelle est la première étape essentielle d’une dissertation philosophique ?',options:['Analyser et définir les termes du sujet','Écrire directement la conclusion','Réciter une citation sans l’expliquer'],correctIndex:0,explanation:'L’analyse des termes permet de comprendre précisément la question et ses enjeux.'),
  Exercise(id:'terminale_fe2',lessonId:'terminale_fl2',question:'La responsabilité consiste principalement à…',options:['Répondre de ses actes et de leurs conséquences','Agir sans tenir compte des autres','Éviter tous les choix'],correctIndex:0,explanation:'Être responsable, c’est pouvoir répondre de ses actes et de leurs effets.'),
  Exercise(id:'terminale_se1',lessonId:'terminale_sl1',question:'À quelle échelle parle-t-on de l’évolution biologique ?',options:['À l’échelle des populations au fil des générations','À l’échelle d’un individu qui décide de changer','À l’échelle d’un seul organe en une journée'],correctIndex:0,explanation:'L’évolution correspond à des changements de fréquences génétiques dans les populations au fil des générations.'),
  Exercise(id:'terminale_se2',lessonId:'terminale_sl2',question:'Une corrélation entre deux phénomènes prouve-t-elle toujours une causalité ?',options:['Oui, toujours','Non, pas nécessairement','Seulement si les phénomènes sont proches'],correctIndex:1,explanation:'Une corrélation indique une association, mais ne suffit pas à démontrer qu’un phénomène cause l’autre.'),
  Exercise(id:'terminale_ae1',lessonId:'terminale_al1',question:'Which phrase introduces a possible solution?',options:['One possible solution would be…','I forgot my bag.','It was yesterday.'],correctIndex:0,explanation:'This phrase introduces a proposed solution to a problem.'),
  Exercise(id:'terminale_ae2',lessonId:'terminale_al2',question:'What is a thesis statement?',options:['The main position of the essay','The writer’s home address','A list of unrelated words'],correctIndex:0,explanation:'A thesis statement clearly presents the central position or argument of an essay.'),

  // Exercices d'application APC : une situation contextualisée en mathématiques et en français pour chaque niveau.
  Exercise(id:'cp1_math_apc',lessonId:'cp1_ml1',question:'À la cantine, tu comptes 7 mangues puis 2 autres. Combien y a-t-il de mangues en tout ?',options:['8','9','10'],correctIndex:1,explanation:'On ajoute 7 et 2 : 7 + 2 = 9.'),
  Exercise(id:'cp1_fr_apc',lessonId:'cp1_fl2',question:'Tu veux écrire une phrase pour dire que Afi joue. Quelle phrase est correcte ?',options:['Afi joue.','joue Afi','Afi jouer'],correctIndex:0,explanation:'Une phrase simple respecte l’ordre des mots et commence par une majuscule.'),
  Exercise(id:'cp2_math_apc',lessonId:'cp2_ml2',question:'Au marché, une vendeuse a 36 oranges. Elle en vend 14. Combien lui en reste-t-il ?',options:['20','22','24'],correctIndex:1,explanation:'On calcule 36 - 14 = 22.'),
  Exercise(id:'cp2_fr_apc',lessonId:'cp2_fl1',question:'Après avoir lu un petit texte, quelle action aide à répondre correctement à une question ?',options:['Inventer une réponse','Chercher l’information dans le texte','Choisir au hasard'],correctIndex:1,explanation:'Une réponse de compréhension doit s’appuyer sur les informations du texte.'),
  Exercise(id:'ce1_math_apc',lessonId:'ce1_ml2',question:'Une classe collecte 125 bouteilles le lundi et 138 le mardi. Combien en a-t-elle collecté au total ?',options:['253','263','273'],correctIndex:1,explanation:'125 + 138 = 263 bouteilles.'),
  Exercise(id:'ce1_fr_apc',lessonId:'ce1_fl2',question:'Tu racontes une visite au jardin scolaire. Quelle information doit apparaître dans ton récit ?',options:['Les événements dans un ordre compréhensible','Des mots sans lien','Uniquement le titre'],correctIndex:0,explanation:'Un récit présente les événements dans un ordre logique.'),
  Exercise(id:'ce2_math_apc',lessonId:'ce2_ml2',question:'Quatre groupes reçoivent chacun 18 cahiers. Combien de cahiers faut-il distribuer ?',options:['62','72','82'],correctIndex:1,explanation:'4 × 18 = 72 cahiers.'),
  Exercise(id:'ce2_fr_apc',lessonId:'ce2_fl2',question:'Tu rédiges un paragraphe sur la propreté de l’école. Comment rendre tes idées claires ?',options:['Les mélanger','Les organiser autour du sujet','Écrire sans ponctuation'],correctIndex:1,explanation:'Un paragraphe organisé développe des idées liées au même sujet.'),
  Exercise(id:'cm1_math_apc',lessonId:'cm1_ml1',question:'Une vendeuse partage équitablement un gâteau en 8 parts et en donne 3. Quelle fraction du gâteau a-t-elle donnée ?',options:['3/8','8/3','5/8'],correctIndex:0,explanation:'Trois parts sur huit représentent 3/8 du gâteau.'),
  Exercise(id:'cm1_fr_apc',lessonId:'cm1_fl1',question:'Dans la phrase « Les élèves nettoient la cour », quel est le sujet ?',options:['nettoient','la cour','Les élèves'],correctIndex:2,explanation:'Le sujet indique qui fait l’action : les élèves.'),
  Exercise(id:'cm2_math_apc',lessonId:'cm2_ml1',question:'Un élève achète un cahier à 750 F et un stylo à 125,5 F. Quel est le montant total ?',options:['875,5 F','865,5 F','885 F'],correctIndex:0,explanation:'750 + 125,5 = 875,5 F.'),
  Exercise(id:'cm2_fr_apc',lessonId:'cm2_fl2',question:'Pour écrire un compte rendu d’une activité scolaire, quelle organisation est la plus claire ?',options:['Début, déroulement, bilan','Des phrases sans ordre','Une liste de mots'],correctIndex:0,explanation:'Un texte organisé présente le contexte, les faits puis le bilan.'),
  Exercise(id:'sixieme_math_apc',lessonId:'l1',question:'Le comité de classe compte 128 cahiers reçus le matin et 75 l’après-midi. Combien de cahiers a-t-il reçus ?',options:['193','203','213'],correctIndex:1,explanation:'128 + 75 = 203 cahiers.'),
  Exercise(id:'sixieme_fr_apc',lessonId:'l7',question:'Dans un texte sur une inondation à Lomé, quelle démarche permet de justifier une réponse ?',options:['Citer un indice du texte','Donner son opinion sans preuve','Recopier le titre seulement'],correctIndex:0,explanation:'Une réponse de compréhension s’appuie sur un indice précis du texte.'),
  Exercise(id:'cinquieme_math_apc',lessonId:'cinq_ml2',question:'Une recette utilise 2/3 de litre d’eau. Quelle fraction équivalente a le même dénominateur 12 ?',options:['4/12','8/12','10/12'],correctIndex:1,explanation:'2/3 = 8/12 en multipliant le numérateur et le dénominateur par 4.'),
  Exercise(id:'cinquieme_fr_apc',lessonId:'cinq_fl1',question:'Pour comprendre le comportement d’un personnage dans un récit, que faut-il examiner ?',options:['Ses actions et les paroles du texte','Uniquement la longueur du texte','La couleur du papier'],correctIndex:0,explanation:'Les actions et les paroles donnent des indices sur le personnage.'),
  Exercise(id:'quatrieme_math_apc',lessonId:'quatre_ml2',question:'Un sac coûte 5 000 F. Le vendeur accorde une réduction de 10 %. Quel est le nouveau prix ?',options:['4 000 F','4 500 F','4 900 F'],correctIndex:1,explanation:'10 % de 5 000 F vaut 500 F ; 5 000 - 500 = 4 500 F.'),
  Exercise(id:'quatrieme_fr_apc',lessonId:'quatre_fl1',question:'Pour convaincre le conseil de ton établissement de planter des arbres, quel élément renforce ton argumentation ?',options:['Un argument accompagné d’un exemple','Une répétition sans explication','Une insulte'],correctIndex:0,explanation:'Un argument expliqué et illustré est plus convaincant.'),
  Exercise(id:'troisieme_math_apc',lessonId:'trois_ml1',question:'Un terrain rectangulaire mesure 6 m sur 8 m. Quelle longueur mesure sa diagonale ?',options:['9 m','10 m','14 m'],correctIndex:1,explanation:'Avec Pythagore : d² = 6² + 8² = 100, donc d = 10 m.'),
  Exercise(id:'troisieme_fr_apc',lessonId:'trois_fl1',question:'Tu défends l’idée qu’il faut protéger les espaces verts. Quelle structure convient à ton texte ?',options:['Thèse, arguments, exemples et conclusion','Une suite de phrases sans lien','Seulement une question'],correctIndex:0,explanation:'Un texte argumentatif présente une thèse, la justifie et conclut.'),
  Exercise(id:'seconde_math_apc',lessonId:'seconde_ml1',question:'Le coût d’un trajet est de 200 F par kilomètre. Si x est la distance, quelle fonction donne le coût ?',options:['f(x)=x+200','f(x)=200x','f(x)=200/x'],correctIndex:1,explanation:'Le coût est proportionnel à la distance : 200 fois le nombre de kilomètres.'),
  Exercise(id:'seconde_fr_apc',lessonId:'seconde_fl2',question:'Dans un paragraphe argumenté sur l’accès à l’eau potable, quel rôle joue l’exemple ?',options:['Illustrer et rendre l’argument concret','Remplacer toute explication','Changer de sujet'],correctIndex:0,explanation:'Un exemple concret aide à comprendre et à soutenir l’argument.'),
  Exercise(id:'premiere_math_apc',lessonId:'premiere_ml1',question:'Une association plante 5 arbres la première semaine puis 3 de plus chaque semaine. Combien en plante-t-elle la quatrième semaine si la suite commence à 5 ?',options:['11','14','17'],correctIndex:1,explanation:'La suite arithmétique a pour premier terme 5 et raison 3 : u4 = 5 + 3×3 = 14.'),
  Exercise(id:'premiere_fr_apc',lessonId:'premiere_fl2',question:'Dans une dissertation, à quoi sert la problématique ?',options:['À formuler la question centrale à examiner','À donner la bibliographie','À remplacer le développement'],correctIndex:0,explanation:'La problématique organise la réflexion autour d’une question centrale.'),
  Exercise(id:'terminale_math_apc',lessonId:'terminale_ml2',question:'Un test médical donne une probabilité de résultat positif de 0,9 chez une personne malade. Comment interpréter 0,9 ?',options:['90 % de résultats positifs parmi les personnes malades','9 personnes sur 10 sont forcément malades','Le test est exact dans tous les cas'],correctIndex:0,explanation:'La probabilité conditionnelle décrit ici la fréquence attendue des tests positifs parmi les personnes malades.'),
  Exercise(id:'terminale_fr_apc',lessonId:'terminale_fl1',question:'Dans une dissertation philosophique sur la liberté, quelle démarche est la plus rigoureuse ?',options:['Définir les notions, poser un problème et argumenter','Donner seulement son avis','Accumuler des citations sans les expliquer'],correctIndex:0,explanation:'Une dissertation construit un problème et développe une argumentation raisonnée.'),
  Exercise(id:'troisieme_bepc2025_systeme',lessonId:'trois_bePC2025_math',question:'Dans le problème inspiré du BEPC 2025, on a x + y = 40 et 5x + 3y = 150. Quelle est la valeur de x ?',options:['10 heures','15 heures','25 heures'],correctIndex:1,explanation:'En remplaçant y par 40 − x : 5x + 3(40 − x) = 150, donc 2x = 30 et x = 15.'),
  Exercise(id:'troisieme_bepc2025_partage',lessonId:'trois_bePC2025_math',question:'On partage 90 000 F proportionnellement aux âges 18, 15 et 12 ans. Quelle somme revient à l’enfant de 15 ans ?',options:['24 000 F','30 000 F','36 000 F'],correctIndex:1,explanation:'La somme des âges vaut 45. Une part vaut 90 000 ÷ 45 = 2 000 F. L’enfant de 15 ans reçoit 15 × 2 000 = 30 000 F.'),
  Exercise(id:'troisieme_bepc2025_fr_comprehension',lessonId:'trois_bepc2025_fr',question:'Dans un récit écrit à la première personne, qui est généralement le narrateur ?',options:['Celui qui raconte en disant « je »','Toujours l’auteur réel','Le lecteur'],correctIndex:0,explanation:'Le narrateur à la première personne raconte les événements en utilisant notamment « je » ou « nous ».'),
  Exercise(id:'troisieme_bepc2025_fr_indirecte',lessonId:'trois_bepc2025_fr',question:'Transforme : « Où vas-tu ? » Elle demande…',options:['où vas-tu ?','où tu vas.','où est-ce que tu vas ?'],correctIndex:1,explanation:'Dans l’interrogation indirecte, on écrit « Elle demande où tu vas. » : l’ordre des mots devient celui d’une proposition déclarative.'),
  Exercise(id:'troisieme_bepc2025_fr_subjonctif',lessonId:'trois_bepc2025_fr',question:'Complète : « Il faut que nous ___ à l’heure. »',options:['sommes','soyons','serons'],correctIndex:1,explanation:'Après « il faut que », on emploie le subjonctif : que nous soyons.'),
  Exercise(id:'cp2_es_mains',lessonId:'cp2_es_lecon1',question:'Que faut-il utiliser pour bien se laver les mains ?',options:['De l’eau et du savon','Du sable seulement','De l’huile'],correctIndex:0,explanation:'L’eau et le savon aident à enlever les saletés et les microbes.'),
  Exercise(id:'cp2_es_poubelle',lessonId:'cp2_es_lecon1',question:'Où dois-tu jeter un papier après la classe ?',options:['Dans la cour','Dans le caniveau','Dans la poubelle'],correctIndex:2,explanation:'La poubelle permet de garder la cour propre.'),
  Exercise(id:'cp2_es_danger',lessonId:'cp2_es_lecon1',question:'Tu trouves des médicaments par terre. Que fais-tu ?',options:['Tu les avales','Tu les donnes à un adulte sans les prendre','Tu joues avec'],correctIndex:1,explanation:'Les médicaments ne sont pas des jouets. Il faut prévenir un adulte.'),
  Exercise(id:'cp2_es_respect',lessonId:'cp2_es_lecon1',question:'Quel geste est gentil envers un camarade ?',options:['Le pousser','Se moquer de lui','L’aider s’il en a besoin'],correctIndex:2,explanation:'Aider un camarade montre le respect et la solidarité.'),
  Exercise(id:'ce1_es_mains',lessonId:'ce1_es_lecon1',question:'Quand faut-il se laver les mains avec de l’eau et du savon ?',options:['Avant de manger et après les toilettes','Seulement avant de dormir','Jamais à l’école'],correctIndex:0,explanation:'Le lavage des mains avant le repas et après les toilettes aide à éviter la transmission des microbes.'),
  Exercise(id:'ce1_es_dechets',lessonId:'ce1_es_lecon1',question:'Où faut-il déposer les papiers après la récréation ?',options:['Dans le caniveau','Dans une poubelle','Dans la cour'],correctIndex:1,explanation:'Les déchets doivent être déposés dans une poubelle ou un point de collecte prévu.'),
  Exercise(id:'ce1_es_danger',lessonId:'ce1_es_lecon1',question:'Tu trouves un flacon inconnu dans la cour. Que fais-tu ?',options:['Tu le goûtes','Tu joues avec','Tu n’y touches pas et tu préviens un adulte'],correctIndex:2,explanation:'Un produit inconnu peut être dangereux. Il faut s’en éloigner et prévenir un adulte.'),
  Exercise(id:'ce1_es_respect',lessonId:'ce1_es_lecon1',question:'Quel geste montre le respect des autres ?',options:['Se moquer d’un camarade','Partager le matériel et aider un camarade','Casser le matériel commun'],correctIndex:1,explanation:'Partager et aider les autres favorise une bonne vie en communauté.'),
  Exercise(id:'ce2_es_hygiene',lessonId:'ce2_es_lecon1',question:'À quel moment faut-il particulièrement se laver les mains ?',options:['Avant de manger et après les toilettes','Seulement le dimanche','Uniquement quand elles sont visibles sales'],correctIndex:0,explanation:'Le lavage des mains avec de l’eau et du savon avant de manger et après les toilettes réduit la transmission de microbes.'),
  Exercise(id:'ce2_es_eau',lessonId:'ce2_es_lecon1',question:'Comment faut-il conserver l’eau potable à la maison ?',options:['Dans un récipient propre et couvert','Dans un récipient ouvert près des déchets','Dans une flaque'],correctIndex:0,explanation:'Un récipient propre et couvert protège l’eau des saletés et des contaminations.'),
  Exercise(id:'ce2_es_securite',lessonId:'ce2_es_lecon1',question:'Tu découvres un produit inconnu dans la cour. Que fais-tu ?',options:['Tu le goûtes','Tu le touches pour jouer','Tu n’y touches pas et tu préviens un adulte'],correctIndex:2,explanation:'Un produit inconnu peut être dangereux : il ne faut ni le toucher ni le goûter.'),
  Exercise(id:'ce2_es_citoyen',lessonId:'ce2_es_lecon1',question:'Quel geste aide à protéger le quartier après la pluie ?',options:['Jeter les déchets dans le caniveau','Participer à une action de salubrité avec des adultes','Laisser les eaux stagnantes sans prévenir'],correctIndex:1,explanation:'Une action collective et encadrée de salubrité aide à garder les caniveaux propres et à limiter les eaux stagnantes.'),
  Exercise(id:'cm2_es_route',lessonId:'cm2_es_lecon1',question:'À moto, quelle attitude protège le mieux la tête du passager ?',options:['Porter un casque correctement attaché','Tenir le casque à la main','Rouler sans casque sur une courte distance'],correctIndex:0,explanation:'Le casque doit être porté sur la tête et correctement attaché pour protéger en cas de chute.'),
  Exercise(id:'cm2_es_feux',lessonId:'cm2_es_lecon1',question:'Que signifie le feu rouge pour un usager de la route ?',options:['Accélérer','S’arrêter','Klaxonner et passer'],correctIndex:1,explanation:'Le feu rouge impose l’arrêt.'),
  Exercise(id:'cm2_es_citoyen',lessonId:'cm2_es_lecon1',question:'Quelle action montre un comportement citoyen à l’école ?',options:['Jeter les déchets dans la cour','Détériorer les tables','Participer à la propreté de la cour'],correctIndex:2,explanation:'Prendre soin des lieux communs et participer à leur propreté est un comportement citoyen.'),
  Exercise(id:'sixieme_annale2024_conversion',lessonId:'sixieme_annale_regio2024_maths',question:'Une distance mesure 3 km. Quelle est sa longueur en mètres ?',options:['300 m','3 000 m','30 000 m'],correctIndex:1,explanation:'1 km = 1 000 m, donc 3 km = 3 × 1 000 = 3 000 m.'),
  Exercise(id:'sixieme_annale2024_poteaux',lessonId:'sixieme_annale_regio2024_maths',question:'Sur une distance de 3 000 m, on place un poteau tous les 20 m, avec un poteau à chaque extrémité. Combien faut-il de poteaux ?',options:['150','151','152'],correctIndex:1,explanation:'3 000 ÷ 20 = 150 intervalles. Il faut un poteau de plus que le nombre d’intervalles : 150 + 1 = 151.'),
  Exercise(id:'sixieme_annale2024_budget',lessonId:'sixieme_annale_regio2024_maths',question:'Le projet coûte 1 093 000 F et le budget est de 1 500 000 F. Combien reste-t-il ?',options:['307 000 F','407 000 F','507 000 F'],correctIndex:1,explanation:'1 500 000 − 1 093 000 = 407 000 F.'),

  Exercise(id:'cp1_math_compter_objets',lessonId:'cp1_math_compter10',question:'Tu as 3 crayons et tu en ajoutes 2. Combien as-tu de crayons ?',options:['4','5','6'],correctIndex:1,explanation:'3 crayons et 2 crayons font 5 crayons.'),
  Exercise(id:'cp1_math_chiffre6',lessonId:'cp1_math_compter10',question:'Quel chiffre représente le nombre six ?',options:['4','6','9'],correctIndex:1,explanation:'Le chiffre 6 représente le nombre six.'),
  Exercise(id:'cp1_math_avant5',lessonId:'cp1_math_compter10',question:'Quel nombre vient juste avant 5 ?',options:['3','4','6'],correctIndex:1,explanation:'Dans l’ordre des nombres, 4 vient juste avant 5.'),
  Exercise(id:'cp1_math_quantite',lessonId:'cp1_math_compter10',question:'Quelle collection contient le plus d’objets ?',options:['2 bouchons','5 bouchons','1 bouchon'],correctIndex:1,explanation:'La collection de 5 bouchons contient plus d’objets que celles de 2 ou 1 bouchon.'),
  Exercise(id:'cp1_math_addition_objets',lessonId:'cp1_math_addition10',question:'Tu as 2 graines et tu en ajoutes 3. Combien as-tu de graines ?',options:['4','5','6'],correctIndex:1,explanation:'2 + 3 = 5. On réunit les deux graines et les trois autres.'),
  Exercise(id:'cp1_math_retirer',lessonId:'cp1_math_addition10',question:'Tu as 6 bouchons et tu en retires 2. Combien en reste-t-il ?',options:['3','4','5'],correctIndex:1,explanation:'6 − 2 = 4. Après avoir retiré deux bouchons, il en reste quatre.'),
  Exercise(id:'cp1_math_situation',lessonId:'cp1_math_addition10',question:'Afi a 3 mangues. Sa maman lui en donne 2. Quelle opération permet de trouver le total ?',options:['3 + 2','3 − 2','2 − 3'],correctIndex:0,explanation:'On ajoute les deux mangues aux trois mangues : 3 + 2 = 5.'),
  Exercise(id:'cp1_fr_syllabe_ma',lessonId:'cp1_fr_syllabes',question:'Quelle syllabe obtient-on avec les sons m et a ?',options:['ma','pa','la'],correctIndex:0,explanation:'Le son /m/ associé au son /a/ forme la syllabe ma.'),
  Exercise(id:'cp1_fr_syllabe_pa',lessonId:'cp1_fr_syllabes',question:'Dans le mot « papa », combien de syllabes entend-on ?',options:['Une','Deux','Trois'],correctIndex:1,explanation:'On prononce pa-pa : le mot contient deux syllabes.'),
  Exercise(id:'cp1_fr_syllabe_mi',lessonId:'cp1_fr_syllabes',question:'Quelle syllabe commence par le son /m/ ?',options:['pa','mi','la'],correctIndex:1,explanation:'Mi commence par le son /m/.'),
  Exercise(id:'cp1_es_mains',lessonId:'cp1_es_lecon1',question:'Avec quoi se lave-t-on les mains ?',options:['De l’eau et du savon','De la peinture','Du sable seulement'],correctIndex:0,explanation:'L’eau et le savon aident à garder les mains propres.'),
  Exercise(id:'cp1_eveil_plante_besoin',lessonId:'cp1_eveil_plante',question:'De quoi une plante a-t-elle besoin pour grandir ?',options:['D’eau, d’air et de lumière','Seulement de bonbons','De fumée'],correctIndex:0,explanation:'L’eau, l’air et la lumière sont nécessaires au développement d’une plante.'),
  Exercise(id:'cp1_eveil_plante_vivant',lessonId:'cp1_eveil_plante',question:'Pourquoi dit-on qu’une plante est un être vivant ?',options:['Parce qu’elle peut grandir','Parce qu’elle est toujours en plastique','Parce qu’elle ne change jamais'],correctIndex:0,explanation:'Une plante est vivante : elle grandit et se développe.'),
  Exercise(id:'cp1_eveil_plante_partie',lessonId:'cp1_eveil_plante',question:'Quelle partie porte généralement les feuilles ?',options:['La tige','La pierre','Le cahier'],correctIndex:0,explanation:'Les feuilles poussent généralement sur la tige ou ses branches.'),
  Exercise(id:'cp1_eveil_plante_geste',lessonId:'cp1_eveil_plante',question:'Quel geste aide à protéger une plante ?',options:['L’arracher','La piétiner','L’arroser sans gaspiller l’eau'],correctIndex:2,explanation:'Arroser raisonnablement et éviter de l’abîmer aide à protéger la plante.'),
  Exercise(id:'cp1_es_dechets',lessonId:'cp1_es_lecon1',question:'Où jeter un papier ?',options:['Par terre','Dans la poubelle','Sur la table'],correctIndex:1,explanation:'On met les déchets dans la poubelle pour garder l’école propre.'),
  Exercise(id:'cp1_es_route',lessonId:'cp1_es_lecon1',question:'Pour traverser la route, que fais-tu ?',options:['Tu cours seul','Tu joues sur la route','Tu demandes l’aide d’un adulte'],correctIndex:2,explanation:'Un adulte aide l’enfant à traverser en sécurité.'),
  Exercise(id:'cp1_es_respect',lessonId:'cp1_es_lecon1',question:'Quel geste est gentil ?',options:['Frapper un camarade','Partager un crayon','Se moquer d’un ami'],correctIndex:1,explanation:'Partager le matériel est un geste de respect et d’entraide.'),

  Exercise(id:'cp2_ml1_dizaines',lessonId:'cp2_ml1',question:'Dans le nombre 63, combien y a-t-il de dizaines ?',options:['3 dizaines','6 dizaines','63 dizaines'],correctIndex:1,explanation:'Dans 63, le chiffre 6 indique six dizaines, soit 60, et le chiffre 3 indique trois unités.'),
  Exercise(id:'cp2_ml1_decomposer',lessonId:'cp2_ml1',question:'Quelle décomposition correspond au nombre 58 ?',options:['50 + 8','5 + 8','80 + 5'],correctIndex:0,explanation:'58 comprend 5 dizaines et 8 unités : 50 + 8.'),
  Exercise(id:'cp2_fl2_majuscule',lessonId:'cp2_fl2',question:'Comment commence une phrase correctement écrite ?',options:['Par une majuscule','Par une virgule','Par un point'],correctIndex:0,explanation:'Une phrase commence par une lettre majuscule.'),
  Exercise(id:'cp2_fl2_point',lessonId:'cp2_fl2',question:'Quel signe termine cette phrase : « Afi va à l’école » ?',options:['Une virgule','Un point','Deux-points'],correctIndex:1,explanation:'Une phrase déclarative se termine généralement par un point.'),
  Exercise(id:'cp2_el1_sens',lessonId:'cp2_el1',question:'Quel organe nous permet d’entendre les sons ?',options:['Les oreilles','Les yeux','Le nez'],correctIndex:0,explanation:'Les oreilles servent à entendre les sons.'),
  Exercise(id:'cp2_el1_yeux',lessonId:'cp2_el1',question:'Quel sens utilisons-nous pour regarder un dessin ?',options:['Le goût','La vue','L’odorat'],correctIndex:1,explanation:'Nous utilisons les yeux et le sens de la vue pour regarder.'),
  Exercise(id:'cp2_el2_eau',lessonId:'cp2_el2',question:'Quelle eau faut-il boire ?',options:['L’eau sale d’un caniveau','L’eau potable','L’eau contenant des déchets'],correctIndex:1,explanation:'L’eau potable est une eau que l’on peut boire sans danger lorsqu’elle est correctement traitée et conservée.'),
  Exercise(id:'cp2_el2_dechets',lessonId:'cp2_el2',question:'Que faut-il faire des déchets de la cour ?',options:['Les jeter dans le caniveau','Les laisser près du puits','Les mettre dans une poubelle'],correctIndex:2,explanation:'Mettre les déchets dans une poubelle aide à garder la cour propre et évite de boucher les caniveaux.'),
  Exercise(id:'cp2_al1_thanks',lessonId:'cp2_al1',question:'What does “Thank you” mean in French ?',options:['Au revoir','Merci','S’il te plaît'],correctIndex:1,explanation:'“Thank you” means “Merci”.'),
  Exercise(id:'cp2_al1_goodbye',lessonId:'cp2_al1',question:'Which word do we use when we leave ?',options:['Goodbye','Hello','Please'],correctIndex:0,explanation:'We say “Goodbye” when we leave.'),
  Exercise(id:'cp2_al2_pencil',lessonId:'cp2_al2',question:'What is “pencil” in French ?',options:['Une chaise','Un crayon','Un sac'],correctIndex:1,explanation:'“Pencil” means “crayon”.'),
  Exercise(id:'cp2_al2_book',lessonId:'cp2_al2',question:'Choose the correct English word for « livre ».',options:['Book','Bag','Ruler'],correctIndex:0,explanation:'“Book” means “livre”.'),

  Exercise(id:'cp1_ml1_compter',lessonId:'cp1_ml1',question:'Afi compte 4 graines puis encore 2 graines. Combien de graines compte-t-elle en tout ?',options:['5','6','7'],correctIndex:1,explanation:'On compte 4 puis 2 de plus : 4 + 2 = 6 graines.'),
  Exercise(id:'cp1_ml1_zero',lessonId:'cp1_ml1',question:'Que signifie le nombre zéro ?',options:['Il y a dix objets','Il n’y a aucun objet','Il y a un objet'],correctIndex:1,explanation:'Zéro indique une quantité nulle : aucun objet.'),
  Exercise(id:'cp1_ml2_cercle',lessonId:'cp1_ml2',question:'Quelle forme est ronde ?',options:['Le triangle','Le carré','Le cercle'],correctIndex:2,explanation:'Le cercle est une forme ronde.'),
  Exercise(id:'cp1_ml2_triangle',lessonId:'cp1_ml2',question:'Combien de côtés possède un triangle ?',options:['Trois','Quatre','Cinq'],correctIndex:0,explanation:'Le triangle possède trois côtés et trois sommets.'),
  Exercise(id:'cp1_fl1_ecouter',lessonId:'cp1_fl1',question:'Que faut-il faire avant de répéter un mot ?',options:['Écouter attentivement','Crier','Tourner le dos'],correctIndex:0,explanation:'On écoute attentivement le mot avant de le répéter correctement.'),
  Exercise(id:'cp1_fl1_respect',lessonId:'cp1_fl1',question:'Quand un camarade parle, quel comportement est correct ?',options:['L’interrompre','Se moquer','L’écouter'],correctIndex:2,explanation:'Écouter les autres sans les interrompre est une attitude respectueuse.'),
  Exercise(id:'cp1_fl2_alphabet',lessonId:'cp1_fl2',question:'Combien de lettres compte l’alphabet français ?',options:['20','26','30'],correctIndex:1,explanation:'L’alphabet français compte 26 lettres.'),
  Exercise(id:'cp1_fl2_prenom',lessonId:'cp1_fl2',question:'Quelle est une bonne première étape pour reconnaître les lettres ?',options:['Apprendre les lettres de son prénom','Écrire sans regarder','Éviter les livres'],correctIndex:0,explanation:'Les lettres de son prénom sont un bon point de départ pour apprendre l’alphabet.'),
  Exercise(id:'cp1_el1_ecole',lessonId:'cp1_el1',question:'Qui accompagne les élèves pour apprendre en classe ?',options:['Le mécanicien','L’enseignant','Le vendeur'],correctIndex:1,explanation:'L’enseignant accompagne les élèves dans leurs apprentissages.'),
  Exercise(id:'cp1_el1_materiel',lessonId:'cp1_el1',question:'Comment faut-il traiter le matériel scolaire ?',options:['Le casser','Le jeter','En prendre soin'],correctIndex:2,explanation:'Prendre soin du matériel permet à tous les élèves de l’utiliser.'),
  Exercise(id:'cp1_el2_mains',lessonId:'cp1_el2',question:'Avec quoi faut-il se laver les mains ?',options:['De l’eau propre et du savon','De l’huile','De la poussière'],correctIndex:0,explanation:'L’eau propre et le savon aident à enlever les saletés et les microbes.'),
  Exercise(id:'cp1_el2_dents',lessonId:'cp1_el2',question:'Quel geste aide à garder les dents propres ?',options:['Manger du sable','Se brosser les dents','Ne jamais se rincer la bouche'],correctIndex:1,explanation:'Le brossage régulier aide à garder les dents propres.'),
  Exercise(id:'cp1_al1_hello',lessonId:'cp1_al1',question:'What does “Hello” mean in French ?',options:['Bonjour','Merci','Au revoir'],correctIndex:0,explanation:'“Hello” signifie “Bonjour”.'),
  Exercise(id:'cp1_al1_bye',lessonId:'cp1_al1',question:'Which expression means “Au revoir” ?',options:['Good morning','Goodbye','Please'],correctIndex:1,explanation:'“Goodbye” signifie “Au revoir”.'),
  Exercise(id:'cp1_al2_one',lessonId:'cp1_al2',question:'What is the English word for « deux » ?',options:['One','Three','Two'],correctIndex:2,explanation:'“Two” signifie “deux”.'),
  Exercise(id:'cp1_al2_five',lessonId:'cp1_al2',question:'Which number means « cinq » ?',options:['Five','Four','One'],correctIndex:0,explanation:'“Five” signifie “cinq”.'),
  Exercise(id:'ce1_ml1_centaines',lessonId:'ce1_ml1',question:'Dans 472, quel chiffre indique les centaines ?',options:['2','7','4'],correctIndex:2,explanation:'Dans 472, 4 représente quatre centaines, soit 400.'),
  Exercise(id:'ce1_ml1_decomposer',lessonId:'ce1_ml1',question:'Quelle décomposition correspond à 326 ?',options:['300 + 20 + 6','30 + 2 + 6','300 + 2 + 60'],correctIndex:0,explanation:'326 = 300 + 20 + 6 : trois centaines, deux dizaines et six unités.'),
  Exercise(id:'ce1_ml2_addition',lessonId:'ce1_ml2',question:'Une classe a 12 cahiers puis reçoit 5 cahiers. Quelle opération faut-il faire ?',options:['12 − 5','12 + 5','12 × 5'],correctIndex:1,explanation:'On réunit deux quantités, donc on additionne : 12 + 5 = 17 cahiers.'),
  Exercise(id:'ce1_ml2_reste',lessonId:'ce1_ml2',question:'Kossi a 15 mangues et en donne 4. Combien lui en reste-t-il ?',options:['11','19','9'],correctIndex:0,explanation:'On enlève 4 à 15 : 15 − 4 = 11 mangues.'),
  Exercise(id:'ce1_fl1_determinant',lessonId:'ce1_fl1',question:'Dans « une maison », quel est le déterminant ?',options:['maison','une','dans'],correctIndex:1,explanation:'« Une » est placé devant le nom « maison » : c’est le déterminant.'),
  Exercise(id:'ce1_fl1_nom',lessonId:'ce1_fl1',question:'Dans « les élèves », quel mot est le nom ?',options:['les','élèves','dans'],correctIndex:1,explanation:'« Élèves » désigne des personnes : c’est le nom.'),
  Exercise(id:'ce1_fl2_personnage',lessonId:'ce1_fl2',question:'Pour comprendre un récit, que faut-il identifier ?',options:['Les personnages','Seulement le nombre de pages','La couleur du cahier'],correctIndex:0,explanation:'Identifier les personnages aide à comprendre qui agit dans l’histoire.'),
  Exercise(id:'ce1_fl2_ordre',lessonId:'ce1_fl2',question:'Quand on raconte une histoire, comment présenter les événements ?',options:['Dans le désordre','Dans l’ordre chronologique','Sans parler de la fin'],correctIndex:1,explanation:'On raconte les événements dans l’ordre : début, événements, fin.'),

  Exercise(id:'ce2_ml1_dizaine',lessonId:'ce2_ml1',question:'Dans 4 582, quel chiffre occupe la position des centaines ?',options:['4','5','8','2'],correctIndex:1,explanation:'Dans 4 582, 4 représente les milliers, 5 les centaines, 8 les dizaines et 2 les unités.'),
  Exercise(id:'ce2_ml1_decomposer',lessonId:'ce2_ml1',question:'Quelle décomposition correspond à 3 406 ?',options:['3 000 + 400 + 6','300 + 40 + 6','3 000 + 40 + 6'],correctIndex:0,explanation:'3 406 = 3 000 + 400 + 6.'),
  Exercise(id:'ce2_ml2_multiplication',lessonId:'ce2_ml2',question:'Combien font 7 × 6 ?',options:['36','42','48'],correctIndex:1,explanation:'7 groupes de 6 donnent 42.'),
  Exercise(id:'ce2_ml2_partage',lessonId:'ce2_ml2',question:'On partage 24 mangues entre 4 enfants. Combien chacun reçoit-il ?',options:['4','6','8'],correctIndex:1,explanation:'24 ÷ 4 = 6 mangues par enfant.'),
  Exercise(id:'ce2_fl1_present',lessonId:'ce2_fl1',question:'Complète : « Nous ___ à l’école. »',options:['va','allons','allez'],correctIndex:1,explanation:'Avec « nous », le verbe aller au présent s’écrit « allons ».'),
  Exercise(id:'ce2_fl1_etre',lessonId:'ce2_fl1',question:'Complète : « Tu ___ un bon élève. »',options:['suis','es','est'],correctIndex:1,explanation:'Avec « tu », le verbe être au présent s’écrit « es ».'),
  Exercise(id:'ce2_fl2_paragraphe',lessonId:'ce2_fl2',question:'Que doit contenir un paragraphe simple ?',options:['Des phrases qui parlent du même sujet','Des mots sans lien','Uniquement des chiffres'],correctIndex:0,explanation:'Les phrases d’un paragraphe développent une même idée ou un même sujet.'),
  Exercise(id:'ce2_fl2_ponctuation',lessonId:'ce2_fl2',question:'Quel signe termine généralement une phrase déclarative ?',options:['Une virgule','Un point','Deux-points'],correctIndex:1,explanation:'Une phrase déclarative se termine généralement par un point.'),
  Exercise(id:'ce2_el1_etats',lessonId:'ce2_el1',question:'Quels sont les trois états de l’eau ?',options:['Solide, liquide et gazeux','Chaud, froid et tiède','Clair, sombre et coloré'],correctIndex:0,explanation:'L’eau existe sous forme solide (glace), liquide et gazeuse (vapeur).'),
  Exercise(id:'ce2_el1_glace',lessonId:'ce2_el1',question:'Que devient la glace lorsqu’elle fond ?',options:['Du sable','De l’eau liquide','De la fumée'],correctIndex:1,explanation:'En fondant, la glace passe de l’état solide à l’état liquide.'),
  Exercise(id:'ce2_el2_dechets',lessonId:'ce2_el2',question:'Quel geste protège l’environnement ?',options:['Jeter les déchets dans le caniveau','Brûler les plastiques partout','Mettre les déchets dans une poubelle'],correctIndex:2,explanation:'Utiliser une poubelle évite de salir les espaces et de boucher les caniveaux.'),
  Exercise(id:'ce2_el2_eau',lessonId:'ce2_el2',question:'Pourquoi faut-il économiser l’eau ?',options:['Parce qu’elle est indispensable à la vie','Parce qu’elle ne sert à rien','Pour salir les rues'],correctIndex:0,explanation:'Les humains, les animaux et les plantes ont besoin d’eau.'),
  Exercise(id:'ce2_al1_numbers',lessonId:'ce2_al1',question:'What is the English word for « quinze » ?',options:['Twelve','Fifteen','Twenty'],correctIndex:1,explanation:'« Fifteen » means quinze.'),
  Exercise(id:'ce2_al1_colour',lessonId:'ce2_al1',question:'What colour is the grass ?',options:['Green','Blue','Black'],correctIndex:0,explanation:'Grass is usually green.'),
  Exercise(id:'ce2_al2_family',lessonId:'ce2_al2',question:'What does « mother » mean in French ?',options:['Père','Mère','Frère'],correctIndex:1,explanation:'« Mother » signifie « mère ».'),
  Exercise(id:'ce2_al2_sister',lessonId:'ce2_al2',question:'How do you say « sœur » in English ?',options:['Brother','Father','Sister'],correctIndex:2,explanation:'« Sister » signifie « sœur ».'),

  Exercise(id:'cm1_ml1_fraction1',lessonId:'cm1_ml1',question:'Quelle fraction représente une part sur quatre parts égales ?',options:['1/2','1/3','1/4'],correctIndex:2,explanation:'Une part parmi quatre parts égales se note 1/4.'),
  Exercise(id:'cm1_ml1_fraction2',lessonId:'cm1_ml1',question:'Dans la fraction 3/5, quel nombre indique le nombre de parts prises ?',options:['3','5','8'],correctIndex:0,explanation:'Le numérateur, placé au-dessus, indique les parts prises : ici 3.'),
  Exercise(id:'cm1_ml2_multiple1',lessonId:'cm1_ml2',question:'Lequel est un multiple de 8 ?',options:['18','24','30'],correctIndex:1,explanation:'8 × 3 = 24 : 24 est donc un multiple de 8.'),
  Exercise(id:'cm1_ml2_division1',lessonId:'cm1_ml2',question:'Combien font 56 ÷ 7 ?',options:['6','7','8'],correctIndex:2,explanation:'7 × 8 = 56, donc 56 ÷ 7 = 8.'),
  Exercise(id:'cm1_fl1_sujet',lessonId:'cm1_fl1',question:'Dans « Les enfants jouent », quel est le sujet ?',options:['Les enfants','jouent','Les'],correctIndex:0,explanation:'« Les enfants » indique qui fait l’action : c’est le sujet.'),
  Exercise(id:'cm1_fl1_verbe',lessonId:'cm1_fl1',question:'Dans « Awa prépare le repas », quel est le verbe ?',options:['Awa','prépare','repas'],correctIndex:1,explanation:'« Prépare » exprime l’action : c’est le verbe.'),
  Exercise(id:'cm1_fl2_temps',lessonId:'cm1_fl2',question:'Dans « Hier, nous avons visité le marché », à quel temps est le verbe ?',options:['Présent','Passé','Futur'],correctIndex:1,explanation:'« Hier » indique une action passée ; « avons visité » est au passé composé.'),
  Exercise(id:'cm1_fl2_futur',lessonId:'cm1_fl2',question:'Quel mot annonce souvent une action future ?',options:['Demain','Hier','Autrefois'],correctIndex:0,explanation:'« Demain » situe l’action dans le futur.'),
  Exercise(id:'cm1_sl1_coeur',lessonId:'cm1_sl1',question:'Quel organe fait circuler le sang dans le corps ?',options:['Le cœur','L’estomac','Le poumon'],correctIndex:0,explanation:'Le cœur agit comme une pompe et propulse le sang.'),
  Exercise(id:'cm1_sl1_respiration',lessonId:'cm1_sl1',question:'Quels organes permettent principalement de respirer ?',options:['Les reins','Les poumons','Les os'],correctIndex:1,explanation:'Les poumons permettent les échanges gazeux pendant la respiration.'),
  Exercise(id:'cm1_sl2_etat',lessonId:'cm1_sl2',question:'La vapeur d’eau est à l’état…',options:['Solide','Liquide','Gazeux'],correctIndex:2,explanation:'La vapeur d’eau est de l’eau à l’état gazeux.'),
  Exercise(id:'cm1_sl2_fusion',lessonId:'cm1_sl2',question:'Comment appelle-t-on le passage de la glace à l’eau liquide ?',options:['La fusion','La solidification','L’évaporation'],correctIndex:0,explanation:'La fusion est le passage de l’état solide à l’état liquide.'),
  Exercise(id:'cm1_al1_routine',lessonId:'cm1_al1',question:'What does « I wake up » mean?',options:['Je me réveille','Je mange','Je dors'],correctIndex:0,explanation:'« I wake up » signifie « je me réveille ».'),
  Exercise(id:'cm1_al1_breakfast',lessonId:'cm1_al1',question:'Which expression means « prendre le petit-déjeuner »?',options:['Go to school','Have breakfast','Go to bed'],correctIndex:1,explanation:'« Have breakfast » signifie prendre le petit-déjeuner.'),
  Exercise(id:'cm1_al2_time',lessonId:'cm1_al2',question:'How do you say 7:00 in English?',options:['It is seven o’clock','It is half past seven','It is six o’clock'],correctIndex:0,explanation:'Pour une heure pile, on dit « seven o’clock ».'),
  Exercise(id:'cm1_al2_half',lessonId:'cm1_al2',question:'What time is « half past three »?',options:['3:00','3:30','4:30'],correctIndex:1,explanation:'« Half past three » signifie trois heures et demie : 3:30.'),

  Exercise(id:'cm2_ml1_decimal1',lessonId:'cm2_ml1',question:'Combien font 12,5 + 3,75 ?',options:['15,25','16,25','16,75'],correctIndex:1,explanation:'12,50 + 3,75 = 16,25. On aligne les virgules avant d’additionner.'),
  Exercise(id:'cm2_ml1_decimal2',lessonId:'cm2_ml1',question:'Calcule 20 − 7,8.',options:['12,2','13,2','12,8'],correctIndex:0,explanation:'20,0 − 7,8 = 12,2.'),
  Exercise(id:'cm2_ml2_perimetre',lessonId:'cm2_ml2',question:'Un rectangle mesure 8 cm de long et 3 cm de large. Quel est son périmètre ?',options:['11 cm','22 cm','24 cm'],correctIndex:1,explanation:'P = 2 × (8 + 3) = 22 cm.'),
  Exercise(id:'cm2_ml2_aire',lessonId:'cm2_ml2',question:'Quelle est l’aire d’un rectangle de 6 cm sur 4 cm ?',options:['10 cm²','20 cm²','24 cm²'],correctIndex:2,explanation:'Aire = longueur × largeur = 6 × 4 = 24 cm².'),
  Exercise(id:'cm2_fl1_accord',lessonId:'cm2_fl1',question:'Choisis la bonne expression.',options:['Les petit filles','Les petites filles','Les petite fille'],correctIndex:1,explanation:'Le déterminant, l’adjectif et le nom s’accordent ici au féminin pluriel.'),
  Exercise(id:'cm2_fl1_pluriel',lessonId:'cm2_fl1',question:'Quel est le pluriel correct de « un cheval » ?',options:['des chevals','des chevaux','des cheval'],correctIndex:1,explanation:'Le pluriel usuel de cheval est chevaux.'),
  Exercise(id:'cm2_fl2_intro',lessonId:'cm2_fl2',question:'À quoi sert l’introduction d’un texte ?',options:['Présenter le sujet','Donner seulement la conclusion','Répéter tous les mots'],correctIndex:0,explanation:'L’introduction présente le thème et prépare le lecteur.'),
  Exercise(id:'cm2_fl2_connecteur',lessonId:'cm2_fl2',question:'Quel connecteur indique une conséquence ?',options:['D’abord','Donc','Ensuite'],correctIndex:1,explanation:'« Donc » introduit une conséquence ou une conclusion.'),
  Exercise(id:'cm2_sl1_energie',lessonId:'cm2_sl1',question:'Quelle source d’énergie est renouvelable ?',options:['Le soleil','Le charbon','Le pétrole'],correctIndex:0,explanation:'L’énergie solaire provient du soleil et se renouvelle naturellement.'),
  Exercise(id:'cm2_sl1_economie',lessonId:'cm2_sl1',question:'Quel geste permet d’économiser l’électricité ?',options:['Laisser toutes les lampes allumées','Éteindre les lampes inutilisées','Ouvrir le réfrigérateur longtemps'],correctIndex:1,explanation:'Éteindre les lampes inutilisées réduit la consommation électrique.'),
  Exercise(id:'cm2_sl2_prevention',lessonId:'cm2_sl2',question:'Quel geste aide à prévenir le paludisme ?',options:['Dormir sous une moustiquaire imprégnée','Boire de l’eau sale','Laisser les eaux stagner'],correctIndex:0,explanation:'La moustiquaire imprégnée protège des piqûres de moustiques vecteurs du paludisme.'),
  Exercise(id:'cm2_sl2_hygiene',lessonId:'cm2_sl2',question:'Quand faut-il se laver les mains ?',options:['Avant de manger et après les toilettes','Jamais','Seulement le dimanche'],correctIndex:0,explanation:'Le lavage des mains aux moments importants limite la transmission des microbes.'),
  Exercise(id:'cm2_al1_direction',lessonId:'cm2_al1',question:'What does « turn left » mean?',options:['Tourne à droite','Tourne à gauche','Continue tout droit'],correctIndex:1,explanation:'« Turn left » signifie « tourne à gauche ».'),
  Exercise(id:'cm2_al1_straight',lessonId:'cm2_al1',question:'How do you say « tout droit » in English?',options:['Go straight','Turn back','Turn right'],correctIndex:0,explanation:'« Go straight » signifie aller tout droit.'),
  Exercise(id:'cm2_al2_yesterday',lessonId:'cm2_al2',question:'Which word means « hier »?',options:['Tomorrow','Yesterday','Today'],correctIndex:1,explanation:'« Yesterday » signifie hier.'),
  Exercise(id:'cm2_al2_tomorrow',lessonId:'cm2_al2',question:'Complete: « Tomorrow, I ___ visit my friend. »',options:['will','was','am yesterday'],correctIndex:0,explanation:'« Will » permet d’exprimer une action future : I will visit.'),

  Exercise(id:'sixieme_nombres_rangs',lessonId:'l1',question:'Dans 5 284, quel est le chiffre des dizaines ?',options:['2','8','4'],correctIndex:1,explanation:'Dans 5 284, 5 représente les milliers, 2 les centaines, 8 les dizaines et 4 les unités.'),
  Exercise(id:'sixieme_nombres_comparer',lessonId:'l1',question:'Quel signe convient : 3 405 ___ 3 450 ?',options:['>','<','='],correctIndex:1,explanation:'Les milliers et les centaines sont identiques ; 0 dizaine est inférieur à 5 dizaines. Donc 3 405 < 3 450.'),
  Exercise(id:'sixieme_decimal_dixieme',lessonId:'l2',question:'Dans 7,36, quel chiffre représente les dixièmes ?',options:['7','3','6'],correctIndex:1,explanation:'Le premier chiffre après la virgule représente les dixièmes : ici 3.'),
  Exercise(id:'sixieme_decimal_compare',lessonId:'l2',question:'Quel est le plus grand nombre ?',options:['4,08','4,8','4,18'],correctIndex:1,explanation:'4,8 = 4,80, qui est supérieur à 4,18 et 4,08.'),
  Exercise(id:'sixieme_addition',lessonId:'l3',question:'Calcule 125,5 + 24,25.',options:['149,75','150,75','149,25'],correctIndex:0,explanation:'125,50 + 24,25 = 149,75.'),
  Exercise(id:'sixieme_soustraction',lessonId:'l3',question:'Calcule 80 − 36,5.',options:['43,5','44,5','46,5'],correctIndex:0,explanation:'80,0 − 36,5 = 43,5.'),
  Exercise(id:'sixieme_multiplication',lessonId:'l4',question:'Combien font 125 × 4 ?',options:['400','500','520'],correctIndex:1,explanation:'125 × 4 = 500.'),
  Exercise(id:'sixieme_produit',lessonId:'l4',question:'Un cahier coûte 250 F. Combien coûtent 6 cahiers ?',options:['1 250 F','1 500 F','1 750 F'],correctIndex:1,explanation:'250 × 6 = 1 500 F.'),
  Exercise(id:'sixieme_longueur_conversion',lessonId:'l5',question:'Combien de centimètres y a-t-il dans 3 mètres ?',options:['30 cm','300 cm','3 000 cm'],correctIndex:1,explanation:'1 m = 100 cm, donc 3 m = 300 cm.'),
  Exercise(id:'sixieme_longueur_addition',lessonId:'l5',question:'Une corde mesure 2 m et une autre 150 cm. Quelle est leur longueur totale en centimètres ?',options:['170 cm','250 cm','350 cm'],correctIndex:2,explanation:'2 m = 200 cm ; 200 + 150 = 350 cm.'),
  Exercise(id:'sixieme_perimetre_carre',lessonId:'l6',question:'Un carré a un côté de 7 cm. Quel est son périmètre ?',options:['14 cm','28 cm','49 cm'],correctIndex:1,explanation:'Le périmètre du carré vaut 4 × côté : 4 × 7 = 28 cm.'),
  Exercise(id:'sixieme_perimetre_rect',lessonId:'l6',question:'Un rectangle mesure 9 cm sur 5 cm. Quel est son périmètre ?',options:['14 cm','28 cm','45 cm'],correctIndex:1,explanation:'P = 2 × (9 + 5) = 28 cm.'),

  Exercise(id:'sixieme_fr_comprehension1',lessonId:'l7',question:'Dans un texte, quelle information trouve-t-on généralement dans le titre ?',options:['Le sujet principal','La liste des réponses','Le nom de tous les lecteurs'],correctIndex:0,explanation:'Le titre annonce le sujet ou l’idée principale du texte.'),
  Exercise(id:'sixieme_fr_comprehension2',lessonId:'l7',question:'Pour comprendre un texte, quelle démarche est la plus utile ?',options:['Lire attentivement et repérer les informations','Choisir une réponse au hasard','Lire uniquement la dernière lettre'],correctIndex:0,explanation:'Une lecture attentive permet d’identifier les personnages, les lieux, les actions et les idées.'),
  Exercise(id:'sixieme_fr_vocabulaire1',lessonId:'l8',question:'Quel mot est un synonyme de « commencer » ?',options:['Débuter','Terminer','Oublier'],correctIndex:0,explanation:'« Débuter » et « commencer » ont un sens proche.'),
  Exercise(id:'sixieme_fr_vocabulaire2',lessonId:'l8',question:'Quel est le contraire de « courageux » ?',options:['Brave','Peureux','Fort'],correctIndex:1,explanation:'« Peureux » exprime une idée contraire à « courageux ».'),
  Exercise(id:'sixieme_fr_phrase1',lessonId:'l9',question:'Quelle phrase est une question ?',options:['Tu viens demain.','Viens ici !','Est-ce que tu viens demain ?'],correctIndex:2,explanation:'Une phrase interrogative pose une question et se termine généralement par un point d’interrogation.'),
  Exercise(id:'sixieme_fr_phrase2',lessonId:'l9',question:'Quel signe termine une phrase exclamative ?',options:['Un point d’exclamation','Une virgule','Un deux-points'],correctIndex:0,explanation:'La phrase exclamative exprime une émotion et se termine par un point d’exclamation.'),
  Exercise(id:'sixieme_fr_sujet1',lessonId:'l10',question:'Dans « Les élèves écrivent », quel est le sujet ?',options:['écrivent','Les élèves','Les'],correctIndex:1,explanation:'« Les élèves » désigne ceux qui font l’action : c’est le sujet.'),
  Exercise(id:'sixieme_fr_sujet2',lessonId:'l10',question:'Dans « Le maître explique la leçon », quel est le verbe ?',options:['maître','leçon','explique'],correctIndex:2,explanation:'« Explique » indique l’action réalisée par le sujet.'),
  Exercise(id:'sixieme_svt_vivant1',lessonId:'l11',question:'Lequel de ces éléments est un être vivant ?',options:['Une pierre','Un manguier','Une chaise'],correctIndex:1,explanation:'Le manguier est un être vivant : il grandit, se nourrit et se reproduit.'),
  Exercise(id:'sixieme_svt_vivant2',lessonId:'l11',question:'Quelle caractéristique est commune aux êtres vivants ?',options:['Ils grandissent et ont besoin de ressources','Ils sont tous immobiles','Ils sont tous fabriqués en métal'],correctIndex:0,explanation:'Les êtres vivants accomplissent des fonctions vitales et se développent.'),
  Exercise(id:'sixieme_svt_plante1',lessonId:'l12',question:'De quoi une plante verte a-t-elle principalement besoin pour grandir ?',options:['D’eau, de lumière et d’air','De pétrole et de plastique','Uniquement de sable sec'],correctIndex:0,explanation:'La plante a besoin notamment d’eau, de lumière, d’air et de sels minéraux.'),
  Exercise(id:'sixieme_svt_plante2',lessonId:'l12',question:'Quelle partie de la plante absorbe principalement l’eau du sol ?',options:['La fleur','Les racines','Le fruit'],correctIndex:1,explanation:'Les racines absorbent l’eau et les sels minéraux présents dans le sol.'),
  Exercise(id:'sixieme_svt_hygiene1',lessonId:'l13',question:'Quel geste limite la transmission des microbes ?',options:['Se laver les mains avec de l’eau et du savon','Partager une serviette sale','Boire dans un récipient souillé'],correctIndex:0,explanation:'Le lavage des mains avec du savon aide à éliminer les microbes.'),
  Exercise(id:'sixieme_svt_hygiene2',lessonId:'l13',question:'Pourquoi faut-il boire de l’eau potable ?',options:['Pour prévenir certaines maladies','Pour remplacer le sommeil','Pour éviter de manger'],correctIndex:0,explanation:'Une eau potable est propre à la consommation et réduit les risques de maladies liées à l’eau contaminée.'),
  Exercise(id:'sixieme_svt_sens1',lessonId:'l14',question:'Quel organe permet principalement de percevoir les sons ?',options:['L’œil','L’oreille','La peau'],correctIndex:1,explanation:'L’oreille est l’organe de l’audition.'),
  Exercise(id:'sixieme_svt_sens2',lessonId:'l14',question:'Quel sens permet de reconnaître une odeur ?',options:['L’odorat','Le goût','Le toucher'],correctIndex:0,explanation:'L’odorat permet de percevoir les odeurs grâce au nez.'),

  Exercise(id:'sixieme_hist_temps1',lessonId:'l15',question:'Sur une frise chronologique, comment classe-t-on généralement les événements ?',options:['Du plus ancien au plus récent','Du plus récent au plus ancien obligatoirement','Par ordre alphabétique'],correctIndex:0,explanation:'La frise chronologique présente les événements dans l’ordre du temps, du plus ancien au plus récent.'),
  Exercise(id:'sixieme_hist_temps2',lessonId:'l15',question:'À quoi sert une date historique ?',options:['À situer un événement dans le temps','À mesurer une distance','À indiquer une direction'],correctIndex:0,explanation:'La date permet de situer précisément un événement dans le temps.'),
  Exercise(id:'sixieme_hist_siecle1',lessonId:'l16',question:'Combien d’années compte un siècle ?',options:['10 ans','50 ans','100 ans'],correctIndex:2,explanation:'Un siècle correspond à une durée de cent années.'),
  Exercise(id:'sixieme_hist_siecle2',lessonId:'l16',question:'L’année 2026 appartient à quel siècle ?',options:['Le XIXe siècle','Le XXe siècle','Le XXIe siècle'],correctIndex:2,explanation:'Les années 2001 à 2100 appartiennent au XXIe siècle.'),
  Exercise(id:'sixieme_geo_continents1',lessonId:'l17',question:'Sur quel continent se trouve le Togo ?',options:['En Afrique','En Asie','En Europe'],correctIndex:0,explanation:'Le Togo est un pays situé en Afrique de l’Ouest.'),
  Exercise(id:'sixieme_geo_continents2',lessonId:'l17',question:'Quel océan borde le littoral du Togo ?',options:['L’océan Indien','L’océan Atlantique','L’océan Pacifique'],correctIndex:1,explanation:'Le Togo possède une façade maritime sur le golfe de Guinée, dans l’océan Atlantique.'),
  Exercise(id:'sixieme_geo_carte1',lessonId:'l18',question:'À quoi sert la légende d’une carte ?',options:['À expliquer les symboles','À donner le prix de la carte','À remplacer le titre'],correctIndex:0,explanation:'La légende indique la signification des couleurs et des symboles utilisés sur la carte.'),
  Exercise(id:'sixieme_geo_carte2',lessonId:'l18',question:'Sur une carte orientée normalement, dans quelle direction se trouve le nord ?',options:['En bas','À droite','En haut'],correctIndex:2,explanation:'Sur la plupart des cartes scolaires, le nord est placé en haut, sauf indication contraire.'),
  Exercise(id:'sixieme_ang_greet1',lessonId:'l19',question:'What does “Good morning” mean in French ?',options:['Bonsoir','Bonjour le matin','Au revoir'],correctIndex:1,explanation:'“Good morning” est une formule de salutation utilisée le matin.'),
  Exercise(id:'sixieme_ang_greet2',lessonId:'l19',question:'How do you introduce yourself ?',options:['My name is Kossi.','Where is the school?','Good night, teacher.'],correctIndex:0,explanation:'“My name is…” signifie « Je m’appelle… ».'),
  Exercise(id:'sixieme_ang_how1',lessonId:'l20',question:'What is the meaning of “How are you?” ?',options:['Quel âge as-tu ?','Comment vas-tu ?','Où habites-tu ?'],correctIndex:1,explanation:'“How are you?” sert à demander à quelqu’un comment il va.'),
  Exercise(id:'sixieme_ang_how2',lessonId:'l20',question:'Choose a polite answer to “How are you?”',options:['I am fine, thank you.','My pencil is blue.','Open the door.'],correctIndex:0,explanation:'“I am fine, thank you” signifie « Je vais bien, merci ».'),
  Exercise(id:'sixieme_ang_objects1',lessonId:'l21',question:'What is “a ruler” in French ?',options:['Un cahier','Une règle','Un tableau'],correctIndex:1,explanation:'“A ruler” signifie « une règle ».'),
  Exercise(id:'sixieme_ang_objects2',lessonId:'l21',question:'Complete: “This is my …” (un livre).',options:['book','desk','bag'],correctIndex:0,explanation:'“Book” signifie « livre » : “This is my book.”'),
  Exercise(id:'sixieme_ang_days1',lessonId:'l22',question:'Which day comes after Monday ?',options:['Sunday','Tuesday','Friday'],correctIndex:1,explanation:'Tuesday (mardi) vient après Monday (lundi).'),
  Exercise(id:'sixieme_ang_days2',lessonId:'l22',question:'Which day is “vendredi” in English ?',options:['Wednesday','Saturday','Friday'],correctIndex:2,explanation:'Friday signifie vendredi.'),
  Exercise(id:'cm2_cepd_math_budget',lessonId:'cm2_ml3',question:'Une école achète 8 cahiers à 350 F chacun et 4 stylos à 125 F chacun. Quelle est la dépense totale ?',options:['3 300 F','3 800 F','4 000 F'],correctIndex:0,explanation:'8 × 350 = 2 800 F et 4 × 125 = 500 F. Total : 2 800 + 500 = 3 300 F.'),
  Exercise(id:'cm2_cepd_math_reste',lessonId:'cm2_ml3',question:'Une association dispose de 15 000 F. Elle dépense 6 750 F pour des fournitures et 3 500 F pour le transport. Quel montant reste-t-il ?',options:['4 750 F','5 250 F','5 750 F'],correctIndex:0,explanation:'Dépenses : 6 750 + 3 500 = 10 250 F. Reste : 15 000 − 10 250 = 4 750 F.'),
  Exercise(id:'cm2_cepd_fr_dictation',lessonId:'cm2_fl4',question:'Quelle phrase est correctement écrite ?',options:['Les enfants ont planté des arbres.','Les enfant on plantés des arbres.','Les enfants ont planter des arbre.'],correctIndex:0,explanation:'« Les enfants » est pluriel ; le verbe avoir s’écrit « ont » et le participe passé « planté » reste ici invariable car le COD suit le verbe.'),
  Exercise(id:'cm2_cepd_fr_comprehension',lessonId:'cm2_fl5',question:'Dans un texte, comment justifier une réponse ?',options:['En donnant un indice précis trouvé dans le texte','En inventant une explication','En recopiant un autre livre'],correctIndex:0,explanation:'Une réponse de compréhension doit s’appuyer sur un passage ou un indice du texte proposé.'),
  Exercise(id:'cm2_cepd_sci_cycle',lessonId:'cm2_sl4',question:'Dans le cycle de l’eau, que se passe-t-il après la condensation des gouttelettes dans les nuages, lorsque celles-ci deviennent lourdes ?',options:['Les précipitations','La disparition de l’eau','La transformation en roche'],correctIndex:0,explanation:'Lorsque les gouttelettes deviennent suffisamment lourdes, elles tombent sous forme de précipitations.'),
  Exercise(id:'cm2_cepd_sci_energy',lessonId:'cm2_sl1',question:'Pourquoi faut-il économiser les sources d’énergie non renouvelables ?',options:['Elles existent en quantité limitée et leur utilisation peut polluer','Elles se renouvellent toutes en quelques minutes','Elles ne servent à rien'],correctIndex:0,explanation:'Le pétrole et le charbon sont limités et leur utilisation produit des pollutions.'),
  Exercise(id:'cm2_cepd_social_safety',lessonId:'cm2_es_lecon1',question:'Avant de traverser une route, que doit faire un piéton ?',options:['Courir sans regarder','S’arrêter, observer les deux côtés et traverser lorsque la voie est libre','Jouer sur la chaussée'],correctIndex:1,explanation:'Le piéton s’arrête, observe attentivement la circulation et traverse seulement lorsque la voie est libre.'),
  Exercise(id:'cm2_cepd_social_citizen',lessonId:'cm2_es_lecon1',question:'Quel comportement protège les biens publics ?',options:['Casser les bancs de l’école','Écrire sur les murs','Utiliser le matériel avec soin et signaler les dégradations'],correctIndex:2,explanation:'Les biens publics appartiennent à tous ; il faut les respecter et les protéger.'),
  Exercise(id:'cm2_fl6_e1',lessonId:'cm2_fl6',question:'Quelle partie d’un récit présente le lieu, le moment et les personnages ?',options:['Le début','La conclusion seulement','La signature'],correctIndex:0,explanation:'La situation initiale présente le cadre et les personnages.'),
  Exercise(id:'cm2_fl6_e2',lessonId:'cm2_fl6',question:'Quel connecteur peut annoncer la dernière action d’un récit ?',options:['Enfin','Parce que','Mais'],correctIndex:0,explanation:'« Enfin » peut introduire la dernière étape d’une suite d’actions.'),
  Exercise(id:'cm2_fl6_e3',lessonId:'cm2_fl6',question:'Que faut-il faire avant de rédiger un récit ?',options:['Préparer les idées et organiser les événements','Écrire sans lire le sujet','Commencer par la signature'],correctIndex:0,explanation:'La préparation aide à respecter le sujet et à raconter les événements dans un ordre logique.'),
  Exercise(id:'cm2_fl6_e4',lessonId:'cm2_fl6',question:'Quel élément doit-on vérifier pendant la relecture ?',options:['Les accords, les verbes et la ponctuation','La couleur des chaussures','Le nombre de dessins'],correctIndex:0,explanation:'La relecture permet de corriger la langue et de vérifier que le récit est compréhensible.'),

  Exercise(id:'cm2_ml3_steps1',lessonId:'cm2_ml3',question:'Une classe achète 12 cahiers à 275 F chacun et 4 stylos à 150 F chacun. Quelle est la dépense totale ?',options:['3 900 F','3 600 F','4 100 F'],correctIndex:0,explanation:'12 × 275 = 3 300 F ; 4 × 150 = 600 F ; 3 300 + 600 = 3 900 F.'),
  Exercise(id:'cm2_ml3_steps2',lessonId:'cm2_ml3',question:'Une coopérative possède 10 000 F. Elle achète 12 cahiers à 275 F chacun et 4 stylos à 150 F chacun. Combien lui reste-t-il ?',options:['6 100 F','6 900 F','5 900 F'],correctIndex:0,explanation:'Les achats coûtent 12 × 275 + 4 × 150 = 3 900 F. Le reste est 10 000 − 3 900 = 6 100 F.'),
  Exercise(id:'cm2_ml3_steps3',lessonId:'cm2_ml3',question:'Pour une sortie, 35 élèves paient chacun 500 F de transport. Le transporteur reçoit 15 000 F d’avance. Combien faut-il encore lui payer ?',options:['2 500 F','3 500 F','4 500 F'],correctIndex:0,explanation:'Le coût total est 35 × 500 = 17 500 F. Après l’avance : 17 500 − 15 000 = 2 500 F.'),
  Exercise(id:'cm2_ml3_steps4',lessonId:'cm2_ml3',question:'Une école reçoit 4 cartons contenant chacun 24 livres. Elle partage tous les livres également entre 6 classes. Combien chaque classe reçoit-elle ?',options:['12 livres','16 livres','18 livres'],correctIndex:1,explanation:'Nombre total : 4 × 24 = 96 livres. Partage : 96 ÷ 6 = 16 livres par classe.'),

  Exercise(id:'cm2_sl5_e1',lessonId:'cm2_sl5',question:'Quels éléments peuvent former un circuit électrique simple ?',options:['Une pile, des fils et une lampe adaptée','Un verre, de l’eau et du sable','Un livre et un crayon'],correctIndex:0,explanation:'Un circuit pédagogique simple utilise une source d’énergie, des conducteurs et un récepteur comme une lampe.'),
  Exercise(id:'cm2_sl5_e2',lessonId:'cm2_sl5',question:'Quand la lampe peut-elle s’allumer ?',options:['Lorsque le circuit est fermé','Lorsque le fil est débranché','Lorsque la boucle est coupée'],correctIndex:0,explanation:'Le circuit fermé forme une boucle qui permet au courant de circuler.'),
  Exercise(id:'cm2_sl5_e3',lessonId:'cm2_sl5',question:'Quel matériau est généralement un isolant électrique ?',options:['Le cuivre','Le fer','Le plastique'],correctIndex:2,explanation:'Le plastique est un matériau isolant dans les conditions habituelles.'),
  Exercise(id:'cm2_sl5_e4',lessonId:'cm2_sl5',question:'Quelle règle faut-il respecter pendant une expérience électrique à l’école ?',options:['Manipuler une prise murale','Utiliser seulement le matériel à très basse tension prévu par l’enseignant','Toucher les fils avec les mains mouillées'],correctIndex:1,explanation:'Les élèves doivent utiliser du matériel pédagogique à très basse tension et ne jamais manipuler le secteur.'),

  Exercise(id:'trois_svt_e1',lessonId:'trois_svt_heredite_ecosysteme',question:'Qu’est-ce qu’un caractère héréditaire ?',options:['Un caractère qui peut être transmis des parents aux enfants','Une blessure passagère','Une habitude apprise uniquement à l’école'],correctIndex:0,explanation:'Un caractère héréditaire peut être transmis d’une génération à l’autre. Certains caractères dépendent aussi de l’environnement.'),
  Exercise(id:'trois_svt_e2',lessonId:'trois_svt_heredite_ecosysteme',question:'Quels éléments peuvent faire partie d’un écosystème ?',options:['Uniquement les animaux','Les êtres vivants et leur milieu non vivant','Uniquement l’eau'],correctIndex:1,explanation:'Un écosystème comprend les êtres vivants et les éléments physiques de leur milieu.'),
  Exercise(id:'trois_svt_e3',lessonId:'trois_svt_heredite_ecosysteme',question:'Dans la chaîne herbe → criquet → grenouille, que mange la grenouille ?',options:['L’herbe','Le criquet','La grenouille'],correctIndex:1,explanation:'La grenouille mange le criquet dans cet exemple de chaîne alimentaire.'),
  Exercise(id:'trois_svt_e4',lessonId:'trois_svt_heredite_ecosysteme',question:'Quel phénomène peut déséquilibrer un écosystème ?',options:['La protection des habitats','La disparition d’une espèce','La plantation d’arbres adaptés'],correctIndex:1,explanation:'La disparition d’une espèce peut perturber les relations alimentaires et l’équilibre du milieu.'),

  Exercise(id:'trois_fr_etude_e1',lessonId:'trois_fr_etude_texte',question:'Quelle est la première étape pour étudier correctement un texte ?',options:['Recopier tout le texte','Lire pour comprendre le thème général','Répondre sans lire'],correctIndex:1,explanation:'Une première lecture permet de comprendre le sujet général avant de rechercher les détails.'),
  Exercise(id:'trois_fr_etude_e2',lessonId:'trois_fr_etude_texte',question:'Quel connecteur introduit généralement un exemple ?',options:['Par exemple','Cependant','Enfin'],correctIndex:0,explanation:'« Par exemple » annonce une illustration concrète d’une idée.'),
  Exercise(id:'trois_fr_etude_e3',lessonId:'trois_fr_etude_texte',question:'Que doit contenir un paragraphe argumentatif ?',options:['Une opinion, des arguments et des exemples','Uniquement une liste de mots','Des phrases sans lien'],correctIndex:0,explanation:'Un paragraphe argumentatif défend une idée à l’aide d’arguments expliqués et illustrés.'),
  Exercise(id:'trois_fr_etude_e4',lessonId:'trois_fr_etude_texte',question:'Pourquoi faut-il relire sa rédaction ?',options:['Pour ajouter des répétitions','Pour vérifier accords, temps et ponctuation','Pour supprimer le titre uniquement'],correctIndex:1,explanation:'La relecture permet de corriger les erreurs de langue et d’améliorer la clarté.'),
  Exercise(id:'trois_ang_opinion_e1',lessonId:'trois_ang_opinion',question:'What does “In my opinion” mean?',options:['À mon avis','À demain','Je ne sais pas'],correctIndex:0,explanation:'“In my opinion” sert à introduire son point de vue : « à mon avis ».'),
  Exercise(id:'trois_ang_opinion_e2',lessonId:'trois_ang_opinion',question:'Which word introduces a reason?',options:['Because','Yesterday','Goodbye'],correctIndex:0,explanation:'Because signifie « parce que » et introduit une raison.'),
  Exercise(id:'trois_ang_opinion_e3',lessonId:'trois_ang_opinion',question:'How can you begin a short letter to a friend?',options:['Dear Kofi,','Yours sincerely','The end yesterday'],correctIndex:0,explanation:'“Dear…” est une formule d’appel utilisée au début d’une lettre.'),
  Exercise(id:'trois_ang_opinion_e4',lessonId:'trois_ang_opinion',question:'Choose the correct sentence.',options:['We should protect our school.','We should protects our school.','We should protecting our school.'],correctIndex:0,explanation:'Après le modal should, le verbe reste à la base verbale : protect.'),
  Exercise(id:'trois_pc_e1',lessonId:'trois_pcl1',question:'Comment branche-t-on un ampèremètre pour mesurer l’intensité ?',options:['En série dans le circuit','En dérivation aux bornes du générateur','Sans le relier au circuit'],correctIndex:0,explanation:'L’ampèremètre se branche en série afin de mesurer l’intensité qui traverse la branche.'),
  Exercise(id:'trois_pc_e2',lessonId:'trois_pcl1',question:'Une résistance de 10 Ω est traversée par un courant de 0,2 A. Quelle est la tension ?',options:['0,2 V','2 V','50 V'],correctIndex:1,explanation:'Loi d’Ohm : U = R × I = 10 × 0,2 = 2 V.'),
  Exercise(id:'trois_pc_e3',lessonId:'trois_pcl1',question:'Quelle unité mesure la tension électrique ?',options:['L’ampère','Le volt','L’ohm'],correctIndex:1,explanation:'La tension se mesure en volts, symbole V.'),
  Exercise(id:'trois_pc_e4',lessonId:'trois_pcl2',question:'Lors d’une transformation chimique, que deviennent les atomes ?',options:['Ils disparaissent','Ils se transforment en énergie uniquement','Ils se réarrangent pour former de nouvelles substances'],correctIndex:2,explanation:'Les atomes sont conservés et se réorganisent dans les produits.'),
  Exercise(id:'trois_pc_e5',lessonId:'trois_pcl2',question:'Quelle équation est équilibrée ?',options:['H₂ + O₂ → H₂O','2 H₂ + O₂ → 2 H₂O','H₂ + O₂ → 2 H₂O'],correctIndex:1,explanation:'À gauche et à droite, il y a quatre atomes d’hydrogène et deux atomes d’oxygène.'),
  Exercise(id:'trois_pc_e6',lessonId:'trois_pcl2',question:'Que faut-il faire au laboratoire ?',options:['Goûter les produits','Respecter les consignes et ne pas respirer directement les vapeurs','Mélanger tous les produits'],correctIndex:1,explanation:'La sécurité impose de suivre les consignes et de ne jamais goûter ou inhaler directement les produits.'),

  Exercise(id:'trois_math_annale_e1',lessonId:'trois_math_annale_bepc',question:'Un triangle rectangle a pour côtés de l’angle droit 6 cm et 8 cm. Quelle est la longueur de l’hypoténuse ?',options:['10 cm','14 cm','100 cm'],correctIndex:0,explanation:'Pythagore : c² = 6² + 8² = 36 + 64 = 100, donc c = 10 cm.'),
  Exercise(id:'trois_math_annale_e2',lessonId:'trois_math_annale_bepc',question:'Quelle égalité permet de vérifier qu’un triangle de côtés 5, 12 et 13 est rectangle ?',options:['5² + 12² = 13²','5 + 12 = 13','5² + 13² = 12²'],correctIndex:0,explanation:'25 + 144 = 169, soit 13². Le triangle est rectangle, avec 13 comme hypoténuse.'),
  Exercise(id:'trois_math_annale_e3',lessonId:'trois_math_annale_bepc',question:'Quelle est la solution de 3x + 5 = 20 ?',options:['x = 15','x = 5','x = 25'],correctIndex:1,explanation:'3x = 20 − 5 = 15, donc x = 15 ÷ 3 = 5.'),
  Exercise(id:'trois_math_annale_e4',lessonId:'trois_math_annale_bepc',question:'Un rectangle mesure 30 m sur 20 m. Quelle est son aire ?',options:['100 m²','50 m²','600 m²'],correctIndex:2,explanation:'Aire = longueur × largeur = 30 × 20 = 600 m².'),

  Exercise(id:'cm2_ml5_budget_e1',lessonId:'cm2_ml5_budget_cepd',question:'Un cahier coûte 500 F. Combien coûtent 4 cahiers ?',options:['1 000 F','2 000 F','2 500 F'],correctIndex:1,explanation:'4 × 500 = 2 000 F.'),
  Exercise(id:'cm2_ml5_budget_e2',lessonId:'cm2_ml5_budget_cepd',question:'Un élève achète 2 cahiers à 500 F et un sac à 3 000 F. Quelle est la dépense totale ?',options:['3 500 F','4 000 F','4 500 F'],correctIndex:1,explanation:'2 × 500 = 1 000 F, puis 1 000 + 3 000 = 4 000 F.'),
  Exercise(id:'cm2_ml5_budget_e3',lessonId:'cm2_ml5_budget_cepd',question:'Avec 5 000 F, quelle monnaie reçoit-on après une dépense de 4 000 F ?',options:['500 F','1 000 F','9 000 F'],correctIndex:1,explanation:'5 000 − 4 000 = 1 000 F.'),
  Exercise(id:'cm2_ml5_budget_e4',lessonId:'cm2_ml5_budget_cepd',question:'Quelle opération calcule le prix de 3 stylos à 200 F chacun ?',options:['200 + 3','200 × 3','200 − 3'],correctIndex:1,explanation:'Pour des objets de même prix, on multiplie le prix unitaire par la quantité : 200 × 3 = 600 F.'),

  Exercise(id:'cm2_fl7_dictation_e1',lessonId:'cm2_fl7_dictation_cepd',question:'Dans « les élèves arrivent », pourquoi écrit-on « arrivent » avec -ent ?',options:['Parce que le sujet est au pluriel','Parce que le sujet est féminin','Parce que la phrase est au passé'],correctIndex:0,explanation:'Le sujet « les élèves » est à la troisième personne du pluriel : le verbe prend -ent au présent.'),
  Exercise(id:'cm2_fl7_dictation_e2',lessonId:'cm2_fl7_dictation_cepd',question:'Quel signe termine normalement une phrase déclarative ?',options:['Une virgule','Un point','Deux-points'],correctIndex:1,explanation:'Une phrase déclarative se termine généralement par un point.'),
  Exercise(id:'cm2_fl7_dictation_e3',lessonId:'cm2_fl7_dictation_cepd',question:'Dans le texte, pourquoi les élèves plantent-ils de jeunes arbres ?',options:['Pour vendre les cahiers','Pour protéger leur environnement','Pour fermer l’école'],correctIndex:1,explanation:'Le texte précise qu’ils plantent de jeunes arbres pour protéger leur environnement.'),
  Exercise(id:'cm2_fl7_dictation_e4',lessonId:'cm2_fl7_dictation_cepd',question:'Quelle est la bonne écriture ?',options:['Chaque matin les élèves arrivent tôt.','chaque matin, les élèves arrivent tôt.','Chaque matin, les élèves arrivent tôt.'],correctIndex:2,explanation:'La phrase commence par une majuscule et la virgule marque la pause après « Chaque matin ».'),

  Exercise(id:'cm2_sl6_dechets_e1',lessonId:'cm2_sl6_dechets',question:'Quel est un danger des déchets jetés dans les caniveaux ?',options:['Ils peuvent les boucher et favoriser les inondations','Ils rendent l’eau potable','Ils font pousser les arbres'],correctIndex:0,explanation:'Les déchets peuvent bloquer l’écoulement de l’eau et contribuer aux inondations.'),
  Exercise(id:'cm2_sl6_dechets_e2',lessonId:'cm2_sl6_dechets',question:'Que signifie réutiliser un objet ?',options:['Le jeter immédiatement','L’employer plusieurs fois','Le brûler dans la cour'],correctIndex:1,explanation:'Réutiliser consiste à prolonger l’usage d’un objet lorsqu’il peut être employé de manière sûre.'),
  Exercise(id:'cm2_sl6_dechets_e3',lessonId:'cm2_sl6_dechets',question:'Quel geste est préférable pour une pile usagée ?',options:['La jeter dans un caniveau','La brûler','La remettre à une collecte adaptée'],correctIndex:2,explanation:'Les piles peuvent contenir des substances dangereuses et doivent être collectées dans une filière adaptée.'),
  Exercise(id:'cm2_sl6_dechets_e4',lessonId:'cm2_sl6_dechets',question:'Quel comportement protège la cour de l’école ?',options:['Jeter les sachets au sol','Utiliser une poubelle et participer à la salubrité','Brûler les déchets près des classes'],correctIndex:1,explanation:'Utiliser une poubelle et garder la cour propre protège le cadre de vie.'),

  Exercise(id:'cm2_shl3_togo_e1',lessonId:'cm2_shl3_togo_regions',question:'Quel pays se trouve à l’ouest du Togo ?',options:['Le Bénin','Le Ghana','Le Burkina Faso'],correctIndex:1,explanation:'Le Ghana est le voisin occidental du Togo.'),
  Exercise(id:'cm2_shl3_togo_e2',lessonId:'cm2_shl3_togo_regions',question:'Quelle région trouve-t-on au nord de la région Centrale ?',options:['La Kara','La Maritime','Les Plateaux'],correctIndex:0,explanation:'Du sud au nord : Maritime, Plateaux, Centrale, Kara et Savanes.'),
  Exercise(id:'cm2_shl3_togo_e3',lessonId:'cm2_shl3_togo_regions',question:'À quoi sert la légende d’une carte ?',options:['À expliquer les symboles et les couleurs','À donner le prix du papier','À remplacer le titre'],correctIndex:0,explanation:'La légende permet de comprendre les signes, couleurs et figurés utilisés sur une carte.'),
  Exercise(id:'cm2_shl3_togo_e4',lessonId:'cm2_shl3_togo_regions',question:'Quel océan borde le Togo au sud ?',options:['L’océan Indien','L’océan Atlantique','L’océan Pacifique'],correctIndex:1,explanation:'Le littoral togolais donne sur le golfe de Guinée, dans l’océan Atlantique.'),

  Exercise(id:'cm2_shl4_histoire_e1',lessonId:'cm2_shl4_histoire_togo',question:'En quelle année l’Allemagne établit-elle un protectorat sur une partie du territoire du Togo actuel ?',options:['1884','1914','1960'],correctIndex:0,explanation:'Le protectorat allemand est établi en 1884.'),
  Exercise(id:'cm2_shl4_histoire_e2',lessonId:'cm2_shl4_histoire_togo',question:'Quelle année marque la fin de la période allemande au Togo pendant la Première Guerre mondiale ?',options:['1884','1914','1945'],correctIndex:1,explanation:'Les forces allemandes se rendent en 1914, pendant la Première Guerre mondiale.'),
  Exercise(id:'cm2_shl4_histoire_e3',lessonId:'cm2_shl4_histoire_togo',question:'À quelle date le Togo devient-il indépendant ?',options:['1er janvier 1960','27 avril 1960','27 avril 1970'],correctIndex:1,explanation:'Le Togo accède à l’indépendance le 27 avril 1960.'),
  Exercise(id:'cm2_shl4_histoire_e4',lessonId:'cm2_shl4_histoire_togo',question:'À quoi sert une frise chronologique ?',options:['À classer des événements dans le temps','À mesurer une distance','À représenter uniquement les montagnes'],correctIndex:0,explanation:'Une frise chronologique permet de placer les événements dans leur ordre temporel.'),

  Exercise(id:'cm2_es_lecon2_e1',lessonId:'cm2_es_lecon2',question:'Lequel est un droit fondamental de l’enfant ?',options:['Le droit à l’éducation','Le droit de frapper les autres','Le droit de détruire le matériel'],correctIndex:0,explanation:'L’éducation fait partie des droits fondamentaux de l’enfant.'),
  Exercise(id:'cm2_es_lecon2_e2',lessonId:'cm2_es_lecon2',question:'Que faire lorsqu’un conflit apparaît entre élèves ?',options:['Se battre','Dialoguer et demander l’aide d’un adulte si nécessaire','Insulter l’autre'],correctIndex:1,explanation:'Le dialogue et l’aide d’un adulte permettent de résoudre un conflit sans violence.'),
  Exercise(id:'cm2_es_lecon2_e3',lessonId:'cm2_es_lecon2',question:'Quel comportement montre la solidarité ?',options:['Se moquer d’un camarade','Aider un camarade isolé','Cacher le matériel commun'],correctIndex:1,explanation:'La solidarité consiste notamment à soutenir et inclure les personnes en difficulté.'),
  Exercise(id:'cm2_es_lecon2_e4',lessonId:'cm2_es_lecon2',question:'Pourquoi respecter le règlement de l’école ?',options:['Pour vivre et apprendre ensemble en sécurité','Pour empêcher les autres d’apprendre','Pour éviter de partager'],correctIndex:0,explanation:'Les règles communes protègent les personnes et facilitent la vie collective.'),
  Exercise(id:'cm2_al3_comm_e1',lessonId:'cm2_al3_communication',question:'Which expression is a polite request?',options:['Give me now!','Can I borrow your pencil, please?','Go away!'],correctIndex:1,explanation:'“Can I borrow your pencil, please?” est une demande polie.'),
  Exercise(id:'cm2_al3_comm_e2',lessonId:'cm2_al3_communication',question:'What does “You’re welcome” mean?',options:['De rien','Au revoir','Excuse-moi'],correctIndex:0,explanation:'“You’re welcome” est une réponse à “Thank you”.'),
  Exercise(id:'cm2_al3_comm_e3',lessonId:'cm2_al3_communication',question:'How do you say « Puis-je entrer ? »?',options:['May I come in?','Where are you?','I am hungry.'],correctIndex:0,explanation:'“May I come in?” signifie « Puis-je entrer ? ».'),
  Exercise(id:'cm2_al3_comm_e4',lessonId:'cm2_al3_communication',question:'Choose the correct answer to “Thank you”.',options:['Good night','You’re welcome','I am ten'],correctIndex:1,explanation:'On répond “You’re welcome” à “Thank you”.'),

  Exercise(id:'ce2_ml4_division_e1',lessonId:'ce2_ml4_division',question:'20 mangues sont partagées équitablement entre 4 enfants. Combien chacun reçoit-il ?',options:['4','5','6'],correctIndex:1,explanation:'20 ÷ 4 = 5 mangues par enfant.'),
  Exercise(id:'ce2_ml4_division_e2',lessonId:'ce2_ml4_division',question:'Dans 23 ÷ 5 = 4 reste 3, quel est le quotient ?',options:['3','4','5'],correctIndex:1,explanation:'Le quotient est 4 et le reste est 3.'),
  Exercise(id:'ce2_ml4_division_e3',lessonId:'ce2_ml4_division',question:'Quelle égalité vérifie 29 ÷ 6 = 4 reste 5 ?',options:['6 × 4 + 5 = 29','6 + 4 + 5 = 29','29 × 6 = 4 + 5'],correctIndex:0,explanation:'Diviseur × quotient + reste = dividende : 6 × 4 + 5 = 29.'),
  Exercise(id:'ce2_ml4_division_e4',lessonId:'ce2_ml4_division',question:'Dans une division avec reste, le reste doit être…',options:['plus grand que le diviseur','égal au dividende','plus petit que le diviseur'],correctIndex:2,explanation:'Le reste est toujours inférieur au diviseur.'),
  Exercise(id:'cm1_fl3_connecteurs_e1',lessonId:'cm1_fl3_connecteurs',question:'Quel connecteur indique une succession ?',options:['D’abord','Pourtant','Parce que'],correctIndex:0,explanation:'« D’abord » annonce la première étape d’une suite d’actions.'),
  Exercise(id:'cm1_fl3_connecteurs_e2',lessonId:'cm1_fl3_connecteurs',question:'Complète : « Il pleut, ___ la cour est mouillée. »',options:['mais','donc','d’abord'],correctIndex:1,explanation:'« Donc » introduit la conséquence.'),
  Exercise(id:'cm1_fl3_connecteurs_e3',lessonId:'cm1_fl3_connecteurs',question:'Quel mot exprime une opposition ?',options:['Ensuite','Car','Cependant'],correctIndex:2,explanation:'« Cependant » marque une opposition.'),
  Exercise(id:'cm1_fl3_connecteurs_e4',lessonId:'cm1_fl3_connecteurs',question:'Quel connecteur peut introduire une cause ?',options:['Parce que','Enfin','Puis'],correctIndex:0,explanation:'« Parce que » introduit une explication ou une cause.'),
  Exercise(id:'trois_pcl3_ohm_e1',lessonId:'trois_pcl3_ohm',question:'Une résistance de 10 Ω est traversée par 0,2 A. Quelle est la tension ?',options:['2 V','5 V','20 V'],correctIndex:0,explanation:'U = R × I = 10 × 0,2 = 2 V.'),
  Exercise(id:'trois_pcl3_ohm_e2',lessonId:'trois_pcl3_ohm',question:'Une tension de 12 V est appliquée à une résistance de 6 Ω. Quelle intensité circule ?',options:['0,5 A','2 A','18 A'],correctIndex:1,explanation:'I = U ÷ R = 12 ÷ 6 = 2 A.'),
  Exercise(id:'trois_pcl3_ohm_e3',lessonId:'trois_pcl3_ohm',question:'U = 9 V et I = 0,3 A. Quelle est la résistance ?',options:['3 Ω','27 Ω','30 Ω'],correctIndex:2,explanation:'R = U ÷ I = 9 ÷ 0,3 = 30 Ω.'),
  Exercise(id:'trois_pcl3_ohm_e4',lessonId:'trois_pcl3_ohm',question:'Quelle unité mesure la résistance électrique ?',options:['Le volt','L’ohm','L’ampère'],correctIndex:1,explanation:'La résistance électrique se mesure en ohms, symbole Ω.'),

  Exercise(id:'cp2_es_lecon2_e1',lessonId:'cp2_es_lecon2',question:'Que faire si tu trouves un médicament inconnu ?',options:['Le goûter','Le laisser et prévenir un adulte','Le donner à un ami'],correctIndex:1,explanation:'Un médicament peut être dangereux s’il est pris sans conseil médical. Préviens un adulte.'),
  Exercise(id:'cp2_es_lecon2_e2',lessonId:'cp2_es_lecon2',question:'Avant de traverser une route, il faut…',options:['Courir sans regarder','Regarder des deux côtés','Jouer sur la route'],correctIndex:1,explanation:'Il faut observer la circulation et traverser prudemment à un endroit sûr.'),
  Exercise(id:'cp2_es_lecon2_e3',lessonId:'cp2_es_lecon2',question:'Qui prévenir en cas de danger ?',options:['Un adulte de confiance','Personne','Un inconnu qui appelle'],correctIndex:0,explanation:'Il faut rapidement avertir un adulte de confiance.'),
  Exercise(id:'cp2_es_lecon2_e4',lessonId:'cp2_es_lecon2',question:'Où faut-il jouer ?',options:['Sur la chaussée','Dans un endroit de jeu sûr','Au milieu des voitures'],correctIndex:1,explanation:'On joue dans un espace prévu et éloigné de la circulation.'),
  Exercise(id:'ce1_es_lecon2_e1',lessonId:'ce1_es_lecon2',question:'Quand faut-il se laver les mains ?',options:['Seulement le dimanche','Avant de manger et après les toilettes','Jamais'],correctIndex:1,explanation:'Le lavage des mains aux moments importants réduit la transmission des microbes.'),
  Exercise(id:'ce1_es_lecon2_e2',lessonId:'ce1_es_lecon2',question:'Comment conserver l’eau de boisson ?',options:['Dans un récipient propre et couvert','Dans une flaque','Dans un récipient sale'],correctIndex:0,explanation:'Un récipient propre et couvert protège l’eau contre les saletés.'),
  Exercise(id:'ce1_es_lecon2_e3',lessonId:'ce1_es_lecon2',question:'Quel geste aide à prévenir le paludisme ?',options:['Laisser de l’eau stagnante','Dormir sous une moustiquaire imprégnée','Jeter les déchets dans les caniveaux'],correctIndex:1,explanation:'La moustiquaire imprégnée aide à se protéger des piqûres de moustiques.'),
  Exercise(id:'ce1_es_lecon2_e4',lessonId:'ce1_es_lecon2',question:'Que faire des déchets ?',options:['Les jeter dans la cour','Les mettre dans une poubelle','Les laisser dans l’eau'],correctIndex:1,explanation:'Les déchets doivent être déposés dans une poubelle ou un lieu de collecte adapté.'),
  Exercise(id:'cm1_es_lecon2_e1',lessonId:'cm1_es_lecon2',question:'Avant d’aider une personne accidentée, il faut d’abord…',options:['Vérifier qu’il n’y a pas de danger','Courir dans la circulation','Toucher un fil électrique'],correctIndex:0,explanation:'Il faut protéger sa propre sécurité et éviter un suraccident.'),
  Exercise(id:'cm1_es_lecon2_e2',lessonId:'cm1_es_lecon2',question:'Quelles informations donner lorsqu’on alerte ?',options:['Le lieu et ce qui s’est passé','Une histoire inventée','Aucune information'],correctIndex:0,explanation:'Des informations précises aident les adultes et les secours à intervenir.'),
  Exercise(id:'cm1_es_lecon2_e3',lessonId:'cm1_es_lecon2',question:'Que faut-il éviter avec une personne inconsciente ?',options:['Alerter un adulte','Lui donner à boire ou un médicament','Rester à l’écart du danger'],correctIndex:1,explanation:'Ne donne rien à boire ou à manger à une personne inconsciente.'),
  Exercise(id:'cm1_es_lecon2_e4',lessonId:'cm1_es_lecon2',question:'Qui doit effectuer les gestes de secours complexes ?',options:['Un enfant seul','Une personne formée','N’importe quel passant sans formation'],correctIndex:1,explanation:'Les gestes complexes doivent être réalisés par des personnes formées.'),

  Exercise(id:'ce2_eveil_lecon3_e1',lessonId:'ce2_eveil_lecon3',question:'Pourquoi ne voit-on généralement pas l’air ?',options:['Parce qu’il est invisible','Parce qu’il n’existe pas','Parce qu’il est toujours solide'],correctIndex:0,explanation:'L’air est un mélange de gaz invisible, mais il occupe de l’espace.'),
  Exercise(id:'ce2_eveil_lecon3_e2',lessonId:'ce2_eveil_lecon3',question:'Quel comportement pollue l’air ?',options:['Planter un arbre','Brûler les déchets près des maisons','Ramasser les déchets'],correctIndex:1,explanation:'La fumée du brûlage des déchets pollue l’air et peut nuire à la santé.'),
  Exercise(id:'ce2_eveil_lecon3_e3',lessonId:'ce2_eveil_lecon3',question:'Quel geste protège la qualité de l’air ?',options:['Brûler les plastiques','Multiplier les feux de déchets','Éviter le brûlage et entretenir les espaces verts'],correctIndex:2,explanation:'Éviter de brûler les déchets et préserver les arbres contribuent à un environnement plus sain.'),
  Exercise(id:'ce2_eveil_lecon3_e4',lessonId:'ce2_eveil_lecon3',question:'Les êtres humains ont besoin d’air notamment pour…',options:['Respirer','Fabriquer des pierres','Éteindre le soleil'],correctIndex:0,explanation:'La respiration utilise l’air et est indispensable à la vie humaine.'),
  Exercise(id:'cm2_ml6_fractions_e1',lessonId:'cm2_ml6_fractions',question:'Dans la fraction 3/4, que signifie le nombre 4 ?',options:['Le nombre de parts égales de l’unité','Le nombre de parts prises','Le résultat d’une addition'],correctIndex:0,explanation:'Le dénominateur indique en combien de parts égales l’unité est partagée.'),
  Exercise(id:'cm2_ml6_fractions_e2',lessonId:'cm2_ml6_fractions',question:'Quelle fraction est la plus grande ?',options:['2/7','5/7','1/7'],correctIndex:1,explanation:'Avec le même dénominateur, le numérateur le plus grand donne la plus grande fraction.'),
  Exercise(id:'cm2_ml6_fractions_e3',lessonId:'cm2_ml6_fractions',question:'Quelle est la moitié de 18 ?',options:['8','9','10'],correctIndex:1,explanation:'18 ÷ 2 = 9.'),
  Exercise(id:'cm2_ml6_fractions_e4',lessonId:'cm2_ml6_fractions',question:'Une galette est partagée en 8 parts égales. Trois parts sont mangées. Quelle fraction reste ?',options:['3/8','5/8','8/5'],correctIndex:1,explanation:'Il reste 8 − 3 = 5 parts sur 8, soit 5/8.'),

  Exercise(id:'cm2_sh_relief_1',lessonId:'cm2_sh_togo_relief',question:'Quel outil explique les signes et les couleurs d’une carte ?',options:['La légende','La couverture','La date'],correctIndex:0,explanation:'La légende explique les couleurs et les signes de la carte.'),
  Exercise(id:'cm2_sh_relief_2',lessonId:'cm2_sh_togo_relief',question:'Quel point cardinal est opposé à l’est ?',options:['Le nord','L’ouest','Le sud'],correctIndex:1,explanation:'L’ouest est opposé à l’est.'),
  Exercise(id:'cm2_sh_relief_3',lessonId:'cm2_sh_togo_relief',question:'La chaîne de l’Atakora est un élément de…',options:['Relief','Littoral uniquement','Réseau routier'],correctIndex:0,explanation:'L’Atakora est un ensemble de reliefs du Togo.'),
  Exercise(id:'cm2_sh_relief_4',lessonId:'cm2_sh_togo_relief',question:'Le Togo se trouve en…',options:['Afrique de l’Ouest','Afrique australe','Europe'],correctIndex:0,explanation:'Le Togo est situé en Afrique de l’Ouest.'),
  Exercise(id:'cm2_sh_eco_1',lessonId:'cm2_sh_activites',question:'Quelle activité consiste à cultiver la terre ?',options:['L’agriculture','Le commerce','Le transport'],correctIndex:0,explanation:'L’agriculture consiste à cultiver des plantes.'),
  Exercise(id:'cm2_sh_eco_2',lessonId:'cm2_sh_activites',question:'Quel est le rôle du commerce ?',options:['Acheter et vendre','Tracer des cartes','Soigner uniquement'],correctIndex:0,explanation:'Le commerce permet l’achat et la vente de produits.'),
  Exercise(id:'cm2_sh_eco_3',lessonId:'cm2_sh_activites',question:'Pourquoi les transports sont-ils utiles ?',options:['Ils facilitent les échanges','Ils empêchent les ventes','Ils remplacent les cultures'],correctIndex:0,explanation:'Les transports déplacent les personnes et les marchandises.'),
  Exercise(id:'cm2_sh_eco_4',lessonId:'cm2_sh_activites',question:'Quel geste favorise une activité durable ?',options:['Protéger les sols et l’eau','Jeter les déchets dans les rivières','Couper tous les arbres'],correctIndex:0,explanation:'Protéger les ressources préserve le milieu.'),
  Exercise(id:'cm2_fr_dict_1',lessonId:'cm2_fr_dictee_accords',question:'Choisis le groupe nominal correctement accordé.',options:['Les petite fille','Les petites filles','Les petits fille'],correctIndex:1,explanation:'Les déterminants, adjectifs et noms sont au féminin pluriel.'),
  Exercise(id:'cm2_fr_dict_2',lessonId:'cm2_fr_dictee_accords',question:'Quelle phrase présente le bon accord ?',options:['Les élèves écrit.','Les élèves écrivent.','Les élèves écris.'],correctIndex:1,explanation:'Le sujet « les élèves » est au pluriel.'),
  Exercise(id:'cm2_fr_dict_3',lessonId:'cm2_fr_dictee_accords',question:'Complète : Il ___ un livre.',options:['à','a','as'],correctIndex:1,explanation:'« A » est le verbe avoir conjugué avec il.'),
  Exercise(id:'cm2_fr_dict_4',lessonId:'cm2_fr_dictee_accords',question:'Complète : Awa ___ sa sœur arrivent.',options:['est','et','à'],correctIndex:1,explanation:'« Et » relie les deux sujets.'),
  Exercise(id:'cm2_math_prop_1',lessonId:'cm2_math_proportion',question:'4 cahiers coûtent 800 F CFA. Prix d’un cahier ?',options:['100 F CFA','200 F CFA','400 F CFA'],correctIndex:1,explanation:'800 ÷ 4 = 200 F CFA.'),
  Exercise(id:'cm2_math_prop_2',lessonId:'cm2_math_proportion',question:'Un cahier coûte 200 F CFA. Prix de 7 cahiers ?',options:['1 200 F CFA','1 400 F CFA','2 000 F CFA'],correctIndex:1,explanation:'7 × 200 = 1 400 F CFA.'),
  Exercise(id:'cm2_math_prop_3',lessonId:'cm2_math_proportion',question:'3 litres coûtent 2 100 F CFA. Prix d’un litre ?',options:['700 F CFA','600 F CFA','900 F CFA'],correctIndex:0,explanation:'2 100 ÷ 3 = 700 F CFA.'),
  Exercise(id:'cm2_math_prop_4',lessonId:'cm2_math_proportion',question:'À 700 F CFA le litre, prix de 5 litres ?',options:['2 800 F CFA','3 500 F CFA','4 200 F CFA'],correctIndex:1,explanation:'5 × 700 = 3 500 F CFA.'),

  Exercise(id:'cinq_math_rel_1',lessonId:'cinq_ml3_operations_relatifs',question:'Calcule (−5) + (−3).',options:['−8','−2','2','8'],correctIndex:0,explanation:'Les deux nombres sont négatifs. On additionne 5 et 3 puis on conserve le signe négatif : −8.'),
  Exercise(id:'cinq_math_rel_2',lessonId:'cinq_ml3_operations_relatifs',question:'Calcule (−9) + 4.',options:['−13','−5','5','13'],correctIndex:1,explanation:'Les signes sont différents. On calcule 9 − 4 = 5 et on garde le signe du nombre ayant la plus grande valeur absolue, −9.'),
  Exercise(id:'cinq_math_rel_3',lessonId:'cinq_ml3_operations_relatifs',question:'Que vaut 7 − (−3) ?',options:['4','−10','10','−4'],correctIndex:2,explanation:'Soustraire −3 revient à ajouter son opposé : 7 + 3 = 10.'),
  Exercise(id:'cinq_math_rel_4',lessonId:'cinq_ml3_operations_relatifs',question:'Sur une droite graduée, quel nombre est le plus grand ?',options:['−6','−2','−9','−12'],correctIndex:1,explanation:'Le nombre le plus grand est le plus à droite. Parmi ces nombres négatifs, −2 est le plus proche de zéro.'),
  Exercise(id:'cinq_fr_text_1',lessonId:'cinq_fl3_types_textes',question:'Quel est le but principal d’un texte argumentatif ?',options:['Raconter une aventure','Défendre une opinion','Décrire un paysage','Donner uniquement des horaires'],correctIndex:1,explanation:'Un texte argumentatif cherche à convaincre ou persuader en présentant une opinion soutenue par des arguments.'),
  Exercise(id:'cinq_fr_text_2',lessonId:'cinq_fl3_types_textes',question:'Quel indice est fréquent dans une description ?',options:['Des adjectifs qualificatifs','Une formule de multiplication','Une liste de dates uniquement','Un dialogue obligatoire'],correctIndex:0,explanation:'Les adjectifs qualificatifs donnent des caractéristiques aux personnes, objets ou lieux décrits.'),
  Exercise(id:'cinq_fr_text_3',lessonId:'cinq_fl3_types_textes',question:'« D’abord, ensuite, enfin » sont surtout des connecteurs…',options:['De cause','D’opposition','Chronologiques','De comparaison'],correctIndex:2,explanation:'Ces connecteurs organisent les événements ou les étapes dans l’ordre du temps.'),
  Exercise(id:'cinq_fr_text_4',lessonId:'cinq_fl3_types_textes',question:'Dans un texte explicatif, on cherche principalement à…',options:['Faire comprendre un phénomène','Faire rire sans expliquer','Cacher les informations','Donner des ordres uniquement'],correctIndex:0,explanation:'Le texte explicatif présente des informations, des causes, des conséquences et des exemples pour faire comprendre.'),
  Exercise(id:'quatre_svt_eco_1',lessonId:'quatre_svt3_protection_ecosystemes',question:'Un écosystème comprend…',options:['Seulement les animaux','Un milieu et les êtres vivants qui y interagissent','Seulement les plantes','Uniquement l’eau'],correctIndex:1,explanation:'Un écosystème associe les organismes vivants et les éléments physiques de leur milieu, avec leurs interactions.'),
  Exercise(id:'quatre_svt_eco_2',lessonId:'quatre_svt3_protection_ecosystemes',question:'Quel rôle jouent les décomposeurs ?',options:['Ils fabriquent la lumière','Ils transforment les restes organiques','Ils empêchent toute croissance','Ils remplacent l’eau'],correctIndex:1,explanation:'Les décomposeurs transforment la matière organique morte et contribuent au recyclage des éléments dans le milieu.'),
  Exercise(id:'quatre_svt_eco_3',lessonId:'quatre_svt3_protection_ecosystemes',question:'La biodiversité désigne…',options:['La diversité du vivant','La quantité de pluie seulement','Le nombre de routes','La température d’un lieu'],correctIndex:0,explanation:'La biodiversité correspond à la diversité des espèces, des individus et des écosystèmes.'),
  Exercise(id:'quatre_svt_eco_4',lessonId:'quatre_svt3_protection_ecosystemes',question:'Quel geste protège un écosystème ?',options:['Brûler les déchets dans la forêt','Détruire les habitats','Limiter la pollution et préserver les habitats','Capturer tous les animaux'],correctIndex:2,explanation:'Réduire la pollution et préserver les habitats aide les espèces à vivre et à se reproduire.'),

  Exercise(id:'seconde_fa_1',lessonId:'seconde_math_fonctions_affines',question:'Dans f(x) = 4x − 7, quel est le coefficient directeur ?',options:['−7','4','7','−4'],correctIndex:1,explanation:'Dans f(x) = ax + b, le coefficient directeur est a. Ici a = 4.'),
  Exercise(id:'seconde_fa_2',lessonId:'seconde_math_fonctions_affines',question:'Si f(x) = 2x + 3, quelle est l’image de 5 ?',options:['10','13','8','15'],correctIndex:1,explanation:'f(5) = 2 × 5 + 3 = 13.'),
  Exercise(id:'seconde_fa_3',lessonId:'seconde_math_fonctions_affines',question:'La fonction f(x) = −2x + 1 est…',options:['Croissante','Décroissante','Constante','Non affine'],correctIndex:1,explanation:'Le coefficient directeur est négatif, donc la fonction est décroissante.'),
  Exercise(id:'seconde_fa_4',lessonId:'seconde_math_fonctions_affines',question:'Un service coûte 300 F CFA plus 150 F CFA par unité x. Quelle expression donne le prix ?',options:['300x + 150','150x + 300','450x','150 + 300'],correctIndex:1,explanation:'Le prix fixe est 300 et chaque unité ajoute 150 : p(x) = 150x + 300.'),
  Exercise(id:'terminale_prob_1',lessonId:'terminale_math_probabilites',question:'Si P(A ∩ B) = 0,12 et P(A) = 0,4, que vaut P_A(B) ?',options:['0,03','0,3','0,52','0,48'],correctIndex:1,explanation:'P_A(B) = 0,12 / 0,4 = 0,3.'),
  Exercise(id:'terminale_prob_2',lessonId:'terminale_math_probabilites',question:'Dans un arbre pondéré, la somme des probabilités des branches issues d’un même nœud vaut…',options:['0','0,5','1','2'],correctIndex:2,explanation:'Les probabilités des issues possibles issues d’un nœud totalisent 1.'),
  Exercise(id:'terminale_prob_3',lessonId:'terminale_math_probabilites',question:'A et B sont indépendants si…',options:['P(A ∩ B) = P(A)P(B)','P(A) = P(B)','P(A ∩ B) = 0 toujours','P(A) + P(B) = 1'],correctIndex:0,explanation:'La définition de l’indépendance est P(A ∩ B) = P(A) × P(B).'),
  Exercise(id:'terminale_prob_4',lessonId:'terminale_math_probabilites',question:'Si P(A)=0,6, P_A(B)=0,5, P(non A)=0,4 et P_nonA(B)=0,25, quelle est P(B) ?',options:['0,2','0,4','0,5','0,75'],correctIndex:1,explanation:'P(B) = 0,6 × 0,5 + 0,4 × 0,25 = 0,40.'),
  Exercise(id:'trois_svt_adn_1',lessonId:'trois_svt_genetique_adn',question:'Quelle molécule porte l’information génétique ?',options:['L’eau','L’ADN','Le glucose','Le dioxygène'],correctIndex:1,explanation:'L’ADN porte l’information génétique chez les êtres vivants.'),
  Exercise(id:'trois_svt_adn_2',lessonId:'trois_svt_genetique_adn',question:'Un allèle est…',options:['Une version d’un gène','Un organe','Une cellule entière','Un nutriment'],correctIndex:0,explanation:'Les allèles sont différentes versions possibles d’un même gène.'),
  Exercise(id:'trois_svt_adn_3',lessonId:'trois_svt_genetique_adn',question:'Lors de la reproduction sexuée, un descendant reçoit une information génétique…',options:['Uniquement du milieu','De chacun des deux parents','Uniquement de la mère','D’aucun parent'],correctIndex:1,explanation:'Chaque parent transmet une partie de son information génétique à la descendance.'),
  Exercise(id:'trois_svt_adn_4',lessonId:'trois_svt_genetique_adn',question:'Pourquoi des frères et sœurs peuvent-ils être différents ?',options:['Ils n’ont aucun gène en commun','Les combinaisons d’informations génétiques peuvent différer','Ils ont toujours le même ADN','L’environnement n’a aucun rôle'],correctIndex:1,explanation:'Les combinaisons génétiques peuvent différer et l’environnement influence aussi certains caractères.'),

  // Renforcement progressif : séries supplémentaires pour les classes de 5e et 4e.
  Exercise(id:'cinq_ml1_rel_2',lessonId:'cinq_ml1',question:'Quel nombre est le plus grand ?',options:['−8','−3','−12','−15'],correctIndex:1,explanation:'Parmi des nombres négatifs, celui qui est le plus proche de zéro est le plus grand : −3.'),
  Exercise(id:'cinq_ml1_rel_3',lessonId:'cinq_ml1',question:'Quel est l’opposé de −14 ?',options:['−14','0','14','1/14'],correctIndex:2,explanation:'L’opposé d’un nombre a le même écart à zéro, mais le signe contraire : l’opposé de −14 est 14.'),
  Exercise(id:'cinq_fl2_gram_2',lessonId:'cinq_fl2',question:'Dans « Le petit garçon court », quel mot est un adjectif qualificatif ?',options:['Le','petit','garçon','court'],correctIndex:1,explanation:'« Petit » précise le nom « garçon » : c’est un adjectif qualificatif.'),
  Exercise(id:'cinq_fl2_gram_3',lessonId:'cinq_fl2',question:'Dans « Elle parle doucement », quel est la classe grammaticale de « doucement » ?',options:['Nom','Verbe','Adverbe','Déterminant'],correctIndex:2,explanation:'« Doucement » précise la manière de parler : c’est un adverbe.'),
  Exercise(id:'cinq_sl1_nut_2',lessonId:'cinq_sl1',question:'Quel groupe alimentaire contribue notamment à construire et réparer les tissus du corps ?',options:['Les protéines','Les boissons sucrées','Les bonbons','Les huiles uniquement'],correctIndex:0,explanation:'Les aliments riches en protéines participent à la croissance et à la réparation des tissus.'),
  Exercise(id:'cinq_sl1_nut_3',lessonId:'cinq_sl1',question:'Quel repas est le plus équilibré ?',options:['Du soda et des bonbons','Du riz, des haricots et des légumes','Uniquement du pain','Uniquement des frites'],correctIndex:1,explanation:'Un repas varié associant féculents, légumineuses et légumes apporte plusieurs nutriments utiles.'),
  Exercise(id:'cinq_sl2_hyg_2',lessonId:'cinq_sl2',question:'À quel moment faut-il particulièrement se laver les mains ?',options:['Seulement le dimanche','Avant de manger et après les toilettes','Uniquement avant de dormir','Jamais si les mains semblent propres'],correctIndex:1,explanation:'Le lavage des mains au savon avant les repas et après les toilettes aide à limiter la transmission des microbes.'),
  Exercise(id:'cinq_sl2_hyg_3',lessonId:'cinq_sl2',question:'Quel geste aide à prévenir le paludisme ?',options:['Dormir sous une moustiquaire imprégnée','Boire de l’eau non traitée','Laisser les eaux stagnantes près de la maison','Garder les déchets ouverts'],correctIndex:0,explanation:'Une moustiquaire imprégnée correctement utilisée réduit les piqûres de moustiques vecteurs du paludisme.'),
  Exercise(id:'cinq_al1_daily_2',lessonId:'cinq_al1',question:'Choose the correct sentence.',options:['She go to school every day.','She goes to school every day.','She going school every day.','She gone to school every day.'],correctIndex:1,explanation:'Au présent simple, on ajoute généralement -s à la troisième personne du singulier : she goes.'),
  Exercise(id:'cinq_al1_daily_3',lessonId:'cinq_al1',question:'What does « usually » mean in French ?',options:['Jamais','Rarement','Habituellement','Demain'],correctIndex:2,explanation:'« Usually » signifie « habituellement » et exprime une fréquence.'),
  Exercise(id:'quatre_ml1_dev_2',lessonId:'quatre_ml1',question:'Développe 2(3x − 4).',options:['6x − 8','5x − 4','6x − 4','3x − 8'],correctIndex:0,explanation:'On distribue 2 à chaque terme : 2 × 3x = 6x et 2 × (−4) = −8.'),
  Exercise(id:'quatre_ml1_dev_3',lessonId:'quatre_ml1',question:'Quelle expression est égale à 5(x + 2) ?',options:['5x + 2','x + 10','5x + 10','7x'],correctIndex:2,explanation:'La distributivité donne 5 × x + 5 × 2 = 5x + 10.'),
  Exercise(id:'quatre_fl2_prop_2',lessonId:'quatre_fl2',question:'Dans « Je pense que tu as raison », la proposition « que tu as raison » est…',options:['Une proposition subordonnée conjonctive','Une proposition indépendante','Une proposition principale','Une proposition infinitive'],correctIndex:0,explanation:'Elle est introduite par la conjonction de subordination « que » et dépend de « Je pense ».'),
  Exercise(id:'quatre_fl2_prop_3',lessonId:'quatre_fl2',question:'Dans « Le livre que tu lis est intéressant », le mot « que » est…',options:['Un déterminant','Un pronom relatif','Une préposition','Un adverbe'],correctIndex:1,explanation:'« Que » reprend le nom « livre » et introduit une proposition subordonnée relative.'),
  Exercise(id:'quatre_sl1_repr_2',lessonId:'quatre_sl1',question:'Chez les humains, la fécondation correspond à…',options:['La fusion d’un spermatozoïde et d’un ovule','La croissance du fœtus','La naissance','La digestion des aliments'],correctIndex:0,explanation:'La fécondation est la rencontre et la fusion d’un spermatozoïde et d’un ovule.'),
  Exercise(id:'quatre_sl1_repr_3',lessonId:'quatre_sl1',question:'Quel organe produit les ovules ?',options:['Les poumons','Les ovaires','Le cœur','Les reins'],correctIndex:1,explanation:'Les ovaires sont les organes reproducteurs qui produisent les ovules.'),
  Exercise(id:'quatre_sl2_eco_2',lessonId:'quatre_sl2',question:'Dans une chaîne alimentaire, les végétaux verts sont généralement…',options:['Des producteurs','Des décomposeurs uniquement','Des consommateurs secondaires','Des prédateurs'],correctIndex:0,explanation:'Les végétaux chlorophylliens fabriquent leur matière organique grâce notamment à la photosynthèse.'),
  Exercise(id:'quatre_sl2_eco_3',lessonId:'quatre_sl2',question:'Quelle action menace directement l’équilibre d’un écosystème ?',options:['Planter des arbres adaptés','Polluer un cours d’eau','Protéger les sols','Préserver les habitats'],correctIndex:1,explanation:'La pollution peut dégrader les habitats et perturber les relations entre les êtres vivants.'),
  Exercise(id:'quatre_al1_past_2',lessonId:'quatre_al1',question:'Complete: « Yesterday, we ___ football. »',options:['play','plays','played','playing'],correctIndex:2,explanation:'« Yesterday » indique le passé ; le prétérit de « play » est « played ».'),
  Exercise(id:'quatre_al1_past_3',lessonId:'quatre_al1',question:'Which question is correct in the past simple ?',options:['Did you visit Lomé?','Do you visited Lomé?','Did you visited Lomé?','Were you visit Lomé?'],correctIndex:0,explanation:'Au prétérit interrogatif, on utilise did + sujet + base verbale : Did you visit...?'),
  Exercise(id:'quatre_al2_future_2',lessonId:'quatre_al2',question:'Complete: « I am going to ___ my grandmother tomorrow. »',options:['visits','visited','visit','visiting'],correctIndex:2,explanation:'Après « be going to », on emploie la base verbale : going to visit.'),
  Exercise(id:'quatre_al2_future_3',lessonId:'quatre_al2',question:'Which expression introduces a future plan ?',options:['Last week','Two days ago','Next month','Yesterday'],correctIndex:2,explanation:'« Next month » signifie « le mois prochain » et situe une action dans le futur.'),

  // Renforcement progressif : exercices de lycée (2nde, 1ère et Terminale).
  Exercise(id:'seconde_ml1_fonctions_3',lessonId:'seconde_ml1',question:'Si f(x) = 3x − 2, quelle est l’image de 4 ?',options:['8','10','12','14'],correctIndex:1,explanation:'f(4) = 3 × 4 − 2 = 12 − 2 = 10.'),
  Exercise(id:'seconde_ml1_fonctions_4',lessonId:'seconde_ml1',question:'Le point A(2 ; 5) appartient à la représentation de f si…',options:['f(2) = 5','f(5) = 2','f(2) = 0','f(0) = 5'],correctIndex:0,explanation:'Un point de coordonnées (x ; y) appartient à la courbe si y = f(x). Ici il faut f(2) = 5.'),
  Exercise(id:'seconde_ml2_factor_2',lessonId:'seconde_ml2',question:'Factorise 6x + 18.',options:['6(x + 3)','3(2x + 18)','6(x + 18)','x(6 + 18)'],correctIndex:0,explanation:'Le facteur commun est 6 : 6x + 18 = 6(x + 3).'),
  Exercise(id:'seconde_ml2_factor_3',lessonId:'seconde_ml2',question:'Développe (x + 4)(x + 2).',options:['x² + 6x + 8','x² + 8','x² + 2x + 4','2x² + 6'],correctIndex:0,explanation:'On distribue : x² + 2x + 4x + 8 = x² + 6x + 8.'),
  Exercise(id:'seconde_fl1_litterature_2',lessonId:'seconde_fl1',question:'Dans l’analyse d’un texte littéraire, que désigne le champ lexical ?',options:['Un ensemble de mots liés à un même thème','La liste des auteurs','Le nombre de paragraphes','La ponctuation uniquement'],correctIndex:0,explanation:'Un champ lexical regroupe des mots qui se rapportent à une même idée ou à un même domaine.'),
  Exercise(id:'seconde_fl1_litterature_3',lessonId:'seconde_fl1',question:'Quelle démarche est la plus pertinente pour justifier une interprétation ?',options:['Donner son avis sans preuve','Citer un passage et expliquer son effet','Recopier tout le texte','Ignorer le vocabulaire'],correctIndex:1,explanation:'Une analyse s’appuie sur des indices précis du texte, cités et expliqués.'),
  Exercise(id:'seconde_sl1_cellule_2',lessonId:'seconde_sl1',question:'Quel élément contient l’essentiel de l’information génétique dans une cellule eucaryote ?',options:['Le noyau','La paroi uniquement','Le milieu extérieur','La membrane seule'],correctIndex:0,explanation:'Dans une cellule eucaryote, l’essentiel de l’ADN est localisé dans le noyau.'),
  Exercise(id:'seconde_sl1_cellule_3',lessonId:'seconde_sl1',question:'Quelle structure délimite la cellule et contrôle les échanges avec son milieu ?',options:['La membrane plasmique','Le chromosome seul','Le nucléole','La vacuole uniquement'],correctIndex:0,explanation:'La membrane plasmique délimite la cellule et participe au contrôle des échanges.'),
  Exercise(id:'seconde_sl2_biodiv_2',lessonId:'seconde_sl2',question:'Pourquoi classe-t-on les êtres vivants ?',options:['Pour comprendre leurs liens de parenté et leur diversité','Pour leur attribuer une valeur commerciale','Pour les ranger par taille seulement','Pour supprimer les espèces rares'],correctIndex:0,explanation:'La classification scientifique permet d’organiser la diversité et de représenter les liens de parenté.'),
  Exercise(id:'seconde_sl2_biodiv_3',lessonId:'seconde_sl2',question:'Deux espèces qui partagent plusieurs caractères dérivés ont généralement…',options:['Des liens de parenté plus étroits','Forcément le même habitat','La même alimentation','La même durée de vie'],correctIndex:0,explanation:'Les caractères dérivés partagés sont des indices de parenté évolutive.'),
  Exercise(id:'premiere_ml1_suites_3',lessonId:'premiere_ml1',question:'Une suite arithmétique a pour premier terme u₀ = 5 et raison r = 3. Quelle est u₄ ?',options:['8','12','17','20'],correctIndex:2,explanation:'u₄ = u₀ + 4r = 5 + 4 × 3 = 17.'),
  Exercise(id:'premiere_ml1_suites_4',lessonId:'premiere_ml1',question:'Une suite géométrique a pour premier terme u₀ = 2 et raison q = 3. Quelle est u₃ ?',options:['6','18','27','54'],correctIndex:3,explanation:'u₃ = u₀ × q³ = 2 × 27 = 54.'),
  Exercise(id:'premiere_ml2_derivee_2',lessonId:'premiere_ml2',question:'Quelle est la dérivée de f(x) = 3x² ?',options:['3x','6x','x³','6'],correctIndex:1,explanation:'La dérivée de x² est 2x ; donc (3x²)′ = 6x.'),
  Exercise(id:'premiere_ml2_derivee_3',lessonId:'premiere_ml2',question:'Si f′(x) est positive sur un intervalle, alors f est…',options:['Décroissante sur cet intervalle','Constante nécessairement','Croissante sur cet intervalle','Nulle partout'],correctIndex:2,explanation:'Une dérivée positive sur un intervalle indique que la fonction y est croissante.'),
  Exercise(id:'premiere_sl1_genetique_2',lessonId:'premiere_sl1',question:'Un gène est…',options:['Une portion d’ADN portant une information','Une cellule entière','Un organe reproducteur','Une protéine toujours complète'],correctIndex:0,explanation:'Un gène est une séquence d’ADN qui porte une information participant notamment à la production d’un ARN ou d’une protéine.'),
  Exercise(id:'premiere_sl1_genetique_3',lessonId:'premiere_sl1',question:'L’expression d’un gène peut conduire à la production…',options:['D’un ARN et parfois d’une protéine','D’un organe directement','D’un chromosome nouveau à chaque instant','D’eau uniquement'],correctIndex:0,explanation:'L’expression d’un gène commence par la transcription en ARN ; certains ARN sont ensuite traduits en protéines.'),
  Exercise(id:'premiere_sl2_immunite_2',lessonId:'premiere_sl2',question:'Quel est le rôle des anticorps ?',options:['Reconnaître spécifiquement certains antigènes','Transporter le dioxygène','Digérer les aliments','Produire l’énergie des muscles'],correctIndex:0,explanation:'Les anticorps se lient spécifiquement à des antigènes et participent à la réponse immunitaire.'),
  Exercise(id:'premiere_sl2_immunite_3',lessonId:'premiere_sl2',question:'La vaccination vise principalement à…',options:['Préparer la mémoire immunitaire','Remplacer tous les globules rouges','Traiter immédiatement toutes les infections','Empêcher toute maladie sans exception'],correctIndex:0,explanation:'La vaccination entraîne le système immunitaire à reconnaître un agent infectieux et à développer une mémoire immunitaire.'),
  Exercise(id:'terminale_ml1_limites_2',lessonId:'terminale_ml1',question:'Quelle est la limite de 1/x lorsque x tend vers +∞ ?',options:['+∞','−∞','0','1'],correctIndex:2,explanation:'Quand x devient très grand et positif, 1/x se rapproche de 0.'),
  Exercise(id:'terminale_ml1_limites_3',lessonId:'terminale_ml1',question:'Quelle est la limite de x² lorsque x tend vers −∞ ?',options:['−∞','+∞','0','1'],correctIndex:1,explanation:'Le carré d’un nombre de grande valeur absolue est positif et augmente sans borne : x² tend vers +∞.'),
  Exercise(id:'terminale_ml2_prob_3',lessonId:'terminale_ml2',question:'Si P(A)=0,5 et P(B|A)=0,8, quelle est P(A ∩ B) ?',options:['0,4','0,3','0,8','1,3'],correctIndex:0,explanation:'P(A ∩ B) = P(A) × P(B|A) = 0,5 × 0,8 = 0,4.'),
  Exercise(id:'terminale_ml2_prob_4',lessonId:'terminale_ml2',question:'Si A et B sont indépendants avec P(A)=0,2 et P(B)=0,5, que vaut P(A ∩ B) ?',options:['0,7','0,3','0,1','0,25'],correctIndex:2,explanation:'Pour deux événements indépendants, P(A ∩ B) = P(A)P(B) = 0,2 × 0,5 = 0,1.'),
  Exercise(id:'terminale_fl1_philo_3',lessonId:'terminale_fl1',question:'Dans une dissertation philosophique, une problématique sert à…',options:['Faire apparaître une difficulté à examiner','Donner uniquement une définition','Énumérer des citations sans lien','Répéter le sujet'],correctIndex:0,explanation:'La problématique transforme le sujet en question argumentée qui fait apparaître une tension ou une difficulté.'),
  Exercise(id:'terminale_fl1_philo_4',lessonId:'terminale_fl1',question:'Quel enchaînement renforce la qualité d’un argument ?',options:['Thèse, justification, exemple ou analyse','Exemple sans explication','Citation sans commentaire','Conclusion avant le raisonnement'],correctIndex:0,explanation:'Un argument doit être formulé, justifié et éclairé par une analyse ou un exemple pertinent.'),
  Exercise(id:'terminale_sl1_evolution_2',lessonId:'terminale_sl1',question:'La sélection naturelle dépend notamment…',options:['De différences héréditaires et du succès reproducteur','Uniquement de la volonté des individus','D’un changement volontaire des gènes','De la taille seule'],correctIndex:0,explanation:'La sélection naturelle modifie la fréquence des caractères héréditaires selon leurs effets sur la survie et la reproduction dans un environnement.'),
  Exercise(id:'terminale_sl1_evolution_3',lessonId:'terminale_sl1',question:'Une mutation est…',options:['Une modification de la séquence de l’ADN','Un déplacement d’un animal','Une division cellulaire ordinaire','Une réponse comportementale apprise'],correctIndex:0,explanation:'Une mutation correspond à une modification de la séquence de l’ADN ; ses effets peuvent être neutres, défavorables ou parfois avantageux.'),
  Exercise(id:'terminale_sl2_sante_2',lessonId:'terminale_sl2',question:'Quel comportement contribue à prévenir les infections sexuellement transmissibles ?',options:['Utiliser correctement un préservatif et se faire dépister','Partager des objets coupants','Ignorer les symptômes','Prendre des antibiotiques sans avis médical'],correctIndex:0,explanation:'L’usage correct du préservatif et le dépistage adapté réduisent les risques ; les conseils d’un professionnel de santé restent importants.'),
  Exercise(id:'terminale_sl2_sante_3',lessonId:'terminale_sl2',question:'Pourquoi faut-il éviter l’automédication avec des antibiotiques ?',options:['Elle favorise les mauvais usages et l’antibiorésistance','Les antibiotiques soignent tous les virus','Elle rend toujours le traitement plus rapide','Elle remplace le diagnostic'],correctIndex:0,explanation:'Les antibiotiques ne traitent pas les infections virales et leur mauvais usage favorise l’antibiorésistance.'),

  // Préparation progressive au BEPC : exercices supplémentaires de 3ème.
  Exercise(id:'trois_ml1_pythagore_2',lessonId:'trois_ml1',question:'Dans un triangle rectangle, les côtés de l’angle droit mesurent 6 cm et 8 cm. Quelle est la longueur de l’hypoténuse ?',options:['10 cm','12 cm','14 cm','48 cm'],correctIndex:0,explanation:'D’après Pythagore, c² = 6² + 8² = 36 + 64 = 100. Donc c = 10 cm.'),
  Exercise(id:'trois_ml1_pythagore_3',lessonId:'trois_ml1',question:'Un triangle a pour côtés 5 cm, 12 cm et 13 cm. Est-il rectangle ?',options:['Oui, car 5² + 12² = 13²','Non, car 5 + 12 ≠ 13','Oui, car 5 × 12 = 13','Impossible à déterminer'],correctIndex:0,explanation:'25 + 144 = 169 = 13². La réciproque du théorème de Pythagore permet de conclure que le triangle est rectangle.'),
  Exercise(id:'trois_ml2_equations_2',lessonId:'trois_ml2',question:'Résous : 3x − 7 = 11.',options:['x = 4','x = 6','x = 8','x = 18'],correctIndex:1,explanation:'3x = 11 + 7 = 18, donc x = 18 ÷ 3 = 6.'),
  Exercise(id:'trois_ml2_equations_3',lessonId:'trois_ml2',question:'Quelle est la solution de 2(x + 3) = 14 ?',options:['x = 3','x = 4','x = 5','x = 7'],correctIndex:1,explanation:'2(x + 3) = 14 donne x + 3 = 7, donc x = 4.'),
  Exercise(id:'trois_fl1_argumentation_2',lessonId:'trois_fl1',question:'Dans un texte argumentatif, une thèse est…',options:['L’idée ou l’opinion que l’auteur défend','La liste des personnages','La dernière phrase seulement','Un mot de liaison'],correctIndex:0,explanation:'La thèse est la position défendue par l’auteur. Les arguments et les exemples servent à la soutenir.'),
  Exercise(id:'trois_fl1_argumentation_3',lessonId:'trois_fl1',question:'Quel connecteur introduit généralement une opposition ?',options:['Donc','Cependant','Parce que','D’abord'],correctIndex:1,explanation:'« Cependant » marque une opposition ou une nuance entre deux idées.'),
  Exercise(id:'trois_pcl1_ohm_2',lessonId:'trois_pcl1',question:'Une résistance de 4 Ω est traversée par un courant de 2 A. Quelle est la tension ?',options:['2 V','6 V','8 V','16 V'],correctIndex:2,explanation:'Loi d’Ohm : U = R × I = 4 × 2 = 8 V.'),
  Exercise(id:'trois_pcl1_ohm_3',lessonId:'trois_pcl1',question:'Quelle unité mesure l’intensité du courant électrique ?',options:['Le volt','L’ampère','L’ohm','Le wattheure'],correctIndex:1,explanation:'L’intensité du courant électrique se mesure en ampères (A).'),
  Exercise(id:'trois_pcl2_chimie_2',lessonId:'trois_pcl2',question:'Lors d’une transformation chimique réalisée dans un système fermé, la masse totale…',options:['Se conserve','Double toujours','Disparaît','Devient nulle'],correctIndex:0,explanation:'La conservation de la masse signifie que la masse totale des réactifs est égale à celle des produits dans un système fermé.'),
  Exercise(id:'trois_pcl2_chimie_3',lessonId:'trois_pcl2',question:'Dans une équation chimique équilibrée, que doit-on conserver ?',options:['Le nombre d’atomes de chaque élément','La couleur des substances','Le nombre de molécules de chaque côté','La température uniquement'],correctIndex:0,explanation:'Une équation chimique doit respecter la conservation des atomes de chaque élément.'),
  Exercise(id:'trois_sl1_heredite_2',lessonId:'trois_sl1',question:'Où se trouve l’essentiel de l’ADN dans une cellule humaine ?',options:['Dans le noyau','Dans le sang uniquement','Dans la membrane plasmique','Dans le milieu extérieur'],correctIndex:0,explanation:'L’essentiel de l’ADN d’une cellule humaine se trouve dans le noyau, organisé en chromosomes.'),
  Exercise(id:'trois_sl2_ecosysteme_2',lessonId:'trois_sl2',question:'Quel exemple illustre une action de protection d’un écosystème ?',options:['Reboiser et limiter les déchets','Brûler systématiquement les forêts','Polluer les cours d’eau','Chasser toutes les espèces'],correctIndex:0,explanation:'Le reboisement et la réduction des déchets contribuent à préserver les habitats et la biodiversité.'),

  // CEPD : série complémentaire de raisonnement, rédaction et connaissances.
  Exercise(id:'cm2_cepd_calc_mental_1',lessonId:'cm2_ml4',question:'Calcule mentalement : 250 + 375.',options:['525','625','675'],correctIndex:1,explanation:'250 + 375 = 250 + 300 + 75 = 625.'),
  Exercise(id:'cm2_cepd_calc_mental_2',lessonId:'cm2_ml4',question:'Combien font 48 × 5 ?',options:['220','240','260'],correctIndex:1,explanation:'48 × 5 = 48 × 10 ÷ 2 = 480 ÷ 2 = 240.'),
  Exercise(id:'cm2_cepd_calc_mental_3',lessonId:'cm2_ml4',question:'Calcule : 1 000 − 398.',options:['602','612','698'],correctIndex:0,explanation:'1 000 − 400 = 600 ; on ajoute 2 : le résultat est 602.'),
  Exercise(id:'cm2_cepd_redaction_1',lessonId:'cm2_fl6',question:'Quel plan convient le mieux pour raconter une sortie scolaire ?',options:['Lieu et moment, déroulement, bilan','Une liste de mots sans ordre','La conclusion avant le début'],correctIndex:0,explanation:'Un récit clair présente d’abord le cadre, raconte ensuite les événements dans l’ordre et termine par un bilan.'),
  Exercise(id:'cm2_cepd_redaction_2',lessonId:'cm2_fl6',question:'Quel connecteur indique qu’un événement vient après un autre ?',options:['Parce que','Ensuite','Pourtant'],correctIndex:1,explanation:'« Ensuite » marque une succession chronologique.'),
  Exercise(id:'cm2_cepd_comprehension_2',lessonId:'cm2_fl5',question:'Un texte dit : « Kossi ferme le robinet après avoir rempli sa bouteille. » Quel geste accomplit-il ?',options:['Il gaspille l’eau','Il économise l’eau','Il pollue la rivière'],correctIndex:1,explanation:'Fermer le robinet après usage évite de gaspiller l’eau.'),
  Exercise(id:'cm2_cepd_science_eau_2',lessonId:'cm2_sl4',question:'Quel phénomène transforme la vapeur d’eau en fines gouttelettes ?',options:['La condensation','L’évaporation','La combustion'],correctIndex:0,explanation:'En se refroidissant, la vapeur d’eau se condense en gouttelettes.'),
  Exercise(id:'cm2_cepd_science_dechets_2',lessonId:'cm2_sl6_dechets',question:'Pourquoi ne faut-il pas jeter les déchets dans les caniveaux ?',options:['Ils peuvent bloquer l’écoulement de l’eau','Ils rendent les routes plus larges','Ils purifient les eaux'],correctIndex:0,explanation:'Les déchets peuvent boucher les caniveaux et contribuer aux inondations.'),
  Exercise(id:'cm2_cepd_geo_regions_5',lessonId:'cm2_shl3_togo_regions',question:'Quelle région administrative du Togo se trouve le plus au nord ?',options:['Maritime','Plateaux','Savanes'],correctIndex:2,explanation:'Du sud au nord, les régions sont Maritime, Plateaux, Centrale, Kara et Savanes.'),
  Exercise(id:'cm2_cepd_geo_neighbors_1',lessonId:'cm2_shl3_togo_regions',question:'Quel pays est situé à l’est du Togo ?',options:['Le Ghana','Le Bénin','Le Burkina Faso'],correctIndex:1,explanation:'Le Bénin se trouve à l’est du Togo.'),
  Exercise(id:'cm2_cepd_civisme_5',lessonId:'cm2_es_lecon2',question:'Un camarade a oublié son matériel. Quelle attitude montre la solidarité ?',options:['Se moquer de lui','L’aider si possible et l’encourager','Cacher ses affaires'],correctIndex:1,explanation:'La solidarité consiste à soutenir un camarade et à l’inclure sans se moquer de lui.'),
  Exercise(id:'cm2_cepd_civisme_6',lessonId:'cm2_es_lecon2',question:'Pourquoi faut-il respecter les biens publics ?',options:['Parce qu’ils sont utiles à toute la communauté','Pour empêcher les autres de les utiliser','Parce qu’ils appartiennent à une seule personne'],correctIndex:0,explanation:'Les biens publics servent à tous ; chacun doit les protéger et en faire un usage responsable.'),

  Exercise(id:"ly_seconde_a4_a4_q1",lessonId:"ly_seconde_a4_a4_l",question:"Quel élément doit soutenir un argument dans une dissertation ?",options:["Une justification et un exemple pertinent","Une répétition du sujet","Une liste sans explication","Une opinion sans raison"],correctIndex:0,explanation:"Un argument solide est expliqué et illustré par un exemple pertinent."),
  Exercise(id:"ly_seconde_a4_a4_q2",lessonId:"ly_seconde_a4_a4_l",question:"À quoi sert une problématique ?",options:["Faire apparaître la question centrale à examiner","Remplacer toute introduction","Donner directement la conclusion","Énumérer les titres"],correctIndex:0,explanation:"La problématique met en évidence le problème auquel le devoir répond."),
  Exercise(id:"ly_seconde_sc_c_c_q1",lessonId:"ly_seconde_sc_c_c_l",question:"Quelle est la dérivée de f(x)=3x² ?",options:["6x","3x","x²","6"],correctIndex:0,explanation:"La règle (xⁿ)' = n xⁿ⁻¹ donne (3x²)' = 6x."),
  Exercise(id:"ly_seconde_sc_c_c_q2",lessonId:"ly_seconde_sc_c_c_l",question:"Quelle unité mesure une force ?",options:["Le newton","Le joule","Le watt","Le volt"],correctIndex:0,explanation:"La force se mesure en newtons (N)."),
  Exercise(id:"ly_seconde_sc_d_d_q1",lessonId:"ly_seconde_sc_d_d_l",question:"Quel est le rôle principal de l'ADN ?",options:["Porter l'information génétique","Transporter l'oxygène dans le sang","Digérer les aliments","Produire la lumière"],correctIndex:0,explanation:"L'ADN porte l'information génétique des cellules."),
  Exercise(id:"ly_seconde_sc_d_d_q2",lessonId:"ly_seconde_sc_d_d_l",question:"Dans un graphique, une variable indépendante est généralement placée sur…",options:["L'axe horizontal","L'axe vertical uniquement","La légende seulement","Le titre"],correctIndex:0,explanation:"La variable indépendante est généralement représentée sur l'axe des abscisses."),
