  Exercise(id:"ly_seconde_g2_g2_q1",lessonId:"ly_seconde_g2_g2_l",question:"Une facture d'achat de fournitures constitue généralement…",options:["Une charge","Un produit de vente","Un capital social","Une créance client"],correctIndex:0,explanation:"Les fournitures consommées dans l'activité constituent généralement une charge."),
  Exercise(id:"ly_seconde_g2_g2_q2",lessonId:"ly_seconde_g2_g2_l",question:"Quel est le montant de 10 % de 50 000 F ?",options:["5 000 F","500 F","10 000 F","50 000 F"],correctIndex:0,explanation:"50 000 × 10/100 = 5 000 F."),
  Exercise(id:"ly_seconde_g3_g3_q1",lessonId:"ly_seconde_g3_g3_l",question:"Quelle est la première étape d'une vente-conseil ?",options:["Identifier le besoin du client","Imposer immédiatement un produit","Établir la facture avant l'échange","Ignorer les questions"],correctIndex:0,explanation:"Il faut d'abord écouter et identifier le besoin du client."),
  Exercise(id:"ly_seconde_g3_g3_q2",lessonId:"ly_seconde_g3_g3_l",question:"À quoi sert une étude de marché ?",options:["Connaître les clients et la concurrence","Remplacer la comptabilité","Fixer un prix au hasard","Supprimer la publicité"],correctIndex:0,explanation:"Une étude de marché aide à comprendre la demande, les clients et les concurrents."),
  Exercise(id:"ly_seconde_e_e_q1",lessonId:"ly_seconde_e_e_l",question:"Quelle grandeur s'exprime en volts ?",options:["La tension électrique","L'intensité","La résistance","La puissance"],correctIndex:0,explanation:"La tension électrique se mesure en volts (V)."),
  Exercise(id:"ly_seconde_e_e_q2",lessonId:"ly_seconde_e_e_l",question:"Quelle relation donne la vitesse moyenne ?",options:["Distance divisée par durée","Durée divisée par distance","Masse multipliée par volume","Force divisée par énergie"],correctIndex:0,explanation:"La vitesse moyenne est égale à la distance parcourue divisée par la durée."),
  Exercise(id:"ly_seconde_f1_f1_q1",lessonId:"ly_seconde_f1_f1_l",question:"À quoi sert la cotation sur un dessin industriel ?",options:["Indiquer les dimensions de la pièce","Décorer le dessin","Remplacer les vues","Indiquer le prix uniquement"],correctIndex:0,explanation:"La cotation précise les dimensions nécessaires à la fabrication et au contrôle."),
  Exercise(id:"ly_seconde_f1_f1_q2",lessonId:"ly_seconde_f1_f1_l",question:"Quel outil sert à mesurer un diamètre avec précision ?",options:["Un pied à coulisse","Un pinceau","Une équerre de tableau","Un compas de dessin seul"],correctIndex:0,explanation:"Le pied à coulisse permet de mesurer des dimensions extérieures, intérieures et des profondeurs."),
  Exercise(id:"ly_seconde_f2_f2_q1",lessonId:"ly_seconde_f2_f2_l",question:"Quel composant limite le courant dans un circuit ?",options:["La résistance","Le haut-parleur","L'interrupteur ouvert seul","La pile vide"],correctIndex:0,explanation:"Une résistance s'oppose au passage du courant et permet d'en limiter l'intensité."),
  Exercise(id:"ly_seconde_f2_f2_q2",lessonId:"ly_seconde_f2_f2_l",question:"Quelle unité mesure l'intensité du courant ?",options:["L'ampère","Le volt","L'ohm","Le watt"],correctIndex:0,explanation:"L'intensité du courant se mesure en ampères (A)."),
  Exercise(id:"ly_seconde_f3_f3_q1",lessonId:"ly_seconde_f3_f3_l",question:"Quel dispositif protège un circuit contre les surintensités ?",options:["Un disjoncteur adapté","Une lampe","Un interrupteur décoratif","Un câble sans protection"],correctIndex:0,explanation:"Un disjoncteur adapté coupe le circuit en cas de surintensité."),
  Exercise(id:"ly_seconde_f3_f3_q2",lessonId:"ly_seconde_f3_f3_l",question:"Avant une intervention électrique, il faut d'abord…",options:["Mettre hors tension et vérifier l'absence de tension","Toucher les conducteurs","Augmenter la charge","Retirer la terre"],correctIndex:0,explanation:"La mise hors tension et la vérification d'absence de tension sont des mesures essentielles, sous encadrement compétent."),
  Exercise(id:"ly_seconde_f4_f4_q1",lessonId:"ly_seconde_f4_f4_l",question:"Quel matériau est couramment utilisé pour réaliser un béton ?",options:["Ciment, granulats et eau","Bois et papier uniquement","Plastique et tissu","Verre et huile"],correctIndex:0,explanation:"Le béton courant est constitué de ciment, d'eau et de granulats, avec éventuellement des adjuvants."),
  Exercise(id:"ly_seconde_f4_f4_q2",lessonId:"ly_seconde_f4_f4_l",question:"Sur un plan, l'échelle 1:100 signifie que 1 cm représente…",options:["100 cm en réalité","1 mm en réalité","10 m en réalité","1 km en réalité"],correctIndex:0,explanation:"À l'échelle 1:100, 1 cm sur le plan représente 100 cm, soit 1 m, en réalité."),
